window.ACDT_CHARGE("paris",[{"id":"wd-Q19675","cat":"musees","ville":"paris","nom":{"fr":"Musée du Louvre","en":"Louvre Museum","es":"Museo del Louvre","de":"Louvre","it":"Museo del Louvre","pt":"Museu do Louvre","nl":"Louvre","pl":"Luwr","ru":"Лувр","uk":"Лувр","ar":"متحف اللوفر","he":"מוזיאון הלובר","tr":"Louvre Müzesi","el":"Μουσείο του Λούβρου","sv":"Louvren","da":"Louvre","nb":"Louvre","fi":"Louvre","cs":"Louvre","sk":"Musée du Louvre","hu":"Louvre","ro":"Muzeul Luvru","bg":"Лувър","hr":"Louvre","sr":"Лувр","sl":"Louvre","lt":"Luvras","lv":"Luvra","et":"Louvre","ca":"Museu del Louvre","eu":"Louvre museoa","is":"Louvre","ga":"Músaem Louvre","sq":"Muzeu i Luvrit","mk":"Лувр","zh-CN":"卢浮宫博物馆","zh-TW":"羅浮宮博物館","ja":"ルーヴル美術館","ko":"루브르 박물관","hi":"लूव्र संग्रहालय","bn":"লুভ্র জাদুঘর","fa":"موزهٔ لوور","th":"พิพิธภัณฑ์ลูฟวร์","vi":"Viện bảo tàng Louvre","id":"Museum Louvre","ms":"Muzium Louvre","fil":"Museo ng Louvre","sw":"Louvre","ur":"لوور","ta":"லூவர் அருங்காட்சியகம்"},"lat":48.861111,"lon":2.335833,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Cour_Napol%C3%A9on_at_night_-_Louvre.jpg/960px-Cour_Napol%C3%A9on_at_night_-_Louvre.jpg","page":"https://commons.wikimedia.org/wiki/File:Cour_Napol%C3%A9on_at_night_-_Louvre.jpg","auteur":"Benh LIEU SONG","licence":"CC BY 2.5"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q19675"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_du_Louvre"}],"recupere":"2026-11-14","court":{"fr":"musée d'art et d'archéologie à Paris, France","en":"art and archeology museum in Paris, France","es":"museo nacional de Francia consagrado al arte anterior al impresionismo","de":"Kunst- und archäologisches Museum in Paris","it":"museo di arte e archeologia a Parigi","pt":"museu de arte e arqueologia francês","nl":"kunstmuseum in Parijs","pl":"muzeum w Paryżu","ru":"музей в Париже, Франция","uk":"музей мистецтва та археології в Парижі, Франція","ar":"متحف بارز من أهم معالم مدينة باريس","he":"מוזיאון לאמנות וארכאולוגיה בפריז, צרפת","tr":"Paris'te arkeoloji ve sanat müzesi","el":"μουσείο τέχνης και αρχαιολογίας στο Παρίσι","sv":"konstmuseum i Paris, Frankrike","da":"kunst- og arkæologimuseum i Paris","nb":"Museum og galleri i Paris","fi":"taidemuseo Ranskassa","cs":"muzeum v Paříži","hu":"művészeti múzeum Párizsban","ro":"muzeu de artă din Paris, Franța","sr":"музеју у Француској","sl":"umetnostni in arheološki muzej v Parizu (Francija)","lt":"muziejus Paryžiuje, Prancūzijoje","lv":"muzejs Parīzē, Francijā","ca":"museu d'art i arqueologia a París, França","eu":"Arte eta arkeologia museoa Parisen","is":"listasafn í París í Frakklandi","ga":"músaem ealaíne agus seandálaíochta i bPáras na Fraince","sq":"muze i arteve","zh-CN":"位于法国巴黎的艺术博物馆","zh-TW":"位於法國巴黎的藝術博物館","ja":"フランス・パリにある美術館","ko":"프랑스 파리에 위치한 국립 박물관","fa":"موزهٔ هنر و باستان‌شناسی در پاریس، فرانسه","vi":"viện bảo tàng nghệ thuật và khảo cổ tại Paris, Pháp","id":"museum di Prancis"},"long":{"pt":"Louvre ou Museu do Louvre é o maior museu de arte do mundo e um monumento histórico em Paris, França. Um marco central da cidade, está localizado na margem direita do rio Sena, no 1º arrondissement (distrito) da cidade. Aproximadamente 38 mil objetos, da pré-história ao século XXI, são exibidos em uma área de 72 735 metros quadrados. Em 2019, o Louvre recebeu 9,6 milhões de visitantes, o que o torna o museu mais visitado do mundo.","pl":"Luwr – dawny pałac królewski w Paryżu, obecnie muzeum sztuki.","ru":"Музей Лувра — один из крупнейших и самый популярный художественный музей мира. Музей расположен в центре Парижа, на правом берегу Сены, на улице Риволи, в 1-м округе столицы.","ja":"ルーヴル美術館 は、パリにあるフランスの国立美術館。世界最大級の美術館（博物館）であるとともに世界最大級の史跡のひとつで、パリ中心部1区のセーヌ川の右岸に位置する。収蔵品38万点以上。先史時代から19世紀までのさまざまな美術品3万5,000点近くが、総面積6万600平方メートルの展示場所で公開されている。世界でもっとも入場者数の多い美術館で、毎年800万人を超える入場者が訪れ、2018年は初めて1,000万人を超えた。フランスの世界遺産であるパリのセーヌ河岸にも包括登録されている。","nl":"Het Louvre is een van 's werelds grootste musea, ondergebracht in een paleis waar eeuwenlang de koningen van Frankrijk resideerden. Het ligt in het 1e arrondissement van de Franse hoofdstad Parijs net ten noorden van de Seine. Het bestaat uit drie vleugels: de Richelieu-vleugel, de Sully-vleugel en de Denon-vleugel. De Mona Lisa van Leonardo da Vinci is waarschijnlijk het beroemdste stuk uit de collectie van het Louvre. Het museum maakt deel uit van de Réunion des musées nationaux et du Grand Palais des Champs-Élysées.","zh-CN":"卢浮宫博物馆 是位于法国巴黎的国立艺术博物馆，同时也是世界上最著名的博物馆之一。博物馆座落于塞纳河右岸的第一区，收藏了大量西方艺术经典作品，包括《蒙娜丽莎》、《米洛的维纳斯》以及《萨莫色雷斯的胜利女神》等。","ko":"루브르 박물관(프랑스어: Musée du Louvre 뮈제 뒤 루브르[*], 영어: Louvre Museum)은 프랑스 파리의 중심가인 리볼리가에 있는 국립 박물관이다. 소장품의 수와 질 면에서 메트로폴리탄 미술관, 대영박물관과 함께 세계적으로 손꼽히는 박물관이다. 현재의 건물은 루브르 궁전을 개조한 것으로, 파리의 센강 주변을 포함하여 세계유산으로 지정되어 있다. 루브르 박물관 앞의 유리 피라미드 조형물인 루브르 피라미드는 근대에 건설된 것으로 한때 어울리지 않다는 평이 많았으나 현재는 루브르를 대표하는 조형물이 되었다. 간단히 루브르라고도 불린다.","ar":"متحف اللوفر، هو متحف فني وطني في باريس، فرنسا، و أحد أشهر المتاحف في العالم. يقع على الضفة الشماليَّة لنهر السين في باريس عاصمة فرنسا.","zh-TW":"羅浮宮博物館 是位於法國巴黎的國立藝術博物館，同時也是世界上最著名的博物館之一。博物館座落於塞納河右岸的第一區，收藏了大量西方藝術經典作品，包括《蒙娜麗莎》、《米洛的維納斯》以及《薩莫色雷斯的勝利女神》等。","fr":"Le musée du Louvre est un musée parisien situé au sein du palais du Louvre dans le 1er arrondissement. Il a le statut de musée national en France. Ordonnées en neuf départements, ses collections présentent l'art occidental du Moyen Âge à 1848, celui des civilisations antiques qui l'ont précédé et influencé, les arts des premiers chrétiens et ceux de l'islam. Avec 72 735 m2 de salles et de galeries, il s'agit du plus grand musée d'art du monde devant le musée de l'Ermitage en Russie et le musée national de Chine.","en":"The Louvre is a national art museum in Paris, France. It is located on the Right Bank of the Seine in the city's 1st arrondissement (district) and home to some of the most canonical works of Western art, including the Mona Lisa, Venus de Milo, and Winged Victory. The museum is housed in the Louvre Palace, originally built in the late 12th to 13th century under Philip II. Remnants of the Medieval Louvre fortress are visible in the basement of the museum. Due to urban expansion, the fortress eventually lost its defensive function, and in 1546 Francis I converted it into the primary residence of the French kings.","it":"Il Museo del Louvre di Parigi, in Francia, è uno dei più celebri musei del mondo e il primo per numero di visitatori. Si trova sulla rive droite, nel primo arrondissement, tra la Senna e rue de Rivoli.","de":"Das Museum Louvre, kurz der Louvre [ˈluːvrə] , ist ein Kunstmuseum im 1. Arrondissement von Paris, der Hauptstadt Frankreichs. Er befindet sich im historischen Schloss Louvre, der ehemaligen Residenz der französischen Könige, am rechten Ufer der Seine. Seit 1793 ist der Louvre als öffentliches Kunstmuseum zugänglich. Nach Napoleon Bonapartes siegreichem Italienfeldzug (1796/97) wurden Kunstwerke in Italien von den Franzosen requiriert. Die so vergrößerte Sammlung wurde in Musée Napoléon umbenannt. Nach dem Ende des Napoleonischen Kaiserreichs (1815) wurde die Kunstsammlung wieder als Louvre bezeichnet.","es":"El museo del Louvre es el museo nacional de Francia consagrado tanto a las bellas artes como a la arqueología y las artes decorativas anteriores al impresionismo. Está ubicado en París, la capital del país, en el antiguo palacio real del Louvre."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Museu_do_Louvre","pl":"https://pl.wikipedia.org/wiki/Luwr","ru":"https://ru.wikipedia.org/wiki/%D0%9B%D1%83%D0%B2%D1%80","ja":"https://ja.wikipedia.org/wiki/%E3%83%AB%E3%83%BC%E3%83%B4%E3%83%AB%E7%BE%8E%E8%A1%93%E9%A4%A8","nl":"https://nl.wikipedia.org/wiki/Louvre","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%B5%AE%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%A6%86","ko":"https://ko.wikipedia.org/wiki/%EB%A3%A8%EB%B8%8C%EB%A5%B4_%EB%B0%95%EB%AC%BC%EA%B4%80","ar":"https://ar.wikipedia.org/wiki/%D9%85%D8%AA%D8%AD%D9%81_%D8%A7%D9%84%D9%84%D9%88%D9%81%D8%B1","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%B5%AE%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%A6%86","fr":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_du_Louvre","en":"https://en.wikipedia.org/wiki/Louvre","it":"https://it.wikipedia.org/wiki/Museo_del_Louvre","de":"https://de.wikipedia.org/wiki/Louvre","es":"https://es.wikipedia.org/wiki/Museo_del_Louvre"},"site":"https://www.louvre.fr/zh-hans"},{"id":"wd-Q2981","cat":"patrimoine","ville":"paris","nom":{"fr":"Cathédrale Notre-Dame de Paris","en":"Notre-Dame de Paris","es":"Catedral de Notre-Dame de París","de":"Notre-Dame de Paris","it":"Notre-Dame di Parigi","pt":"Notre-Dame de Paris","nl":"Notre-Dame van Parijs","pl":"Katedra Notre-Dame w Paryżu","ru":"Собор Парижской Богоматери","uk":"Собор Паризької Богоматері","ar":"كاتدرائية سيدة باريس","he":"נוטרדאם","tr":"Notre Dame Katedrali","el":"Καθεδρικός Ναός της Παναγίας των Παρισίων","sv":"Notre-Dame de Paris","da":"Notre Dame","nb":"Notre-Dame de Paris","fi":"Notre Dame","cs":"Katedrála Notre-Dame","sk":"Katedrála Notre-Dame","hu":"Notre-Dame","ro":"Notre-Dame de Paris","bg":"Света Богородица","hr":"Katedrala Notre-Dame u Parizu","sr":"Нотр Дам","sl":"Stolnica Notre-Dame v Parizu","lt":"Paryžiaus Dievo Motinos katedra","lv":"Parīzes Dievmātes katedrāle","et":"Notre-Dame","ca":"Notre-Dame de París","eu":"Parisko Notre-Dame katedrala","is":"Notre Dame","ga":"Ardeaglais Notre Dame","sq":"Notre-Dame de Paris","mk":"Богородична црква","zh-CN":"巴黎圣母院","zh-TW":"巴黎聖母院","ja":"ノートルダム大聖堂","ko":"노트르담 대성당","hi":"नोत्र-दाम द पारी","bn":"নোত্র্‌ দাম দ্য পারি","fa":"کلیسای نوتردام پاریس","th":"อาสนวิหารน็อทร์-ดามแห่งปารีส","vi":"Nhà thờ Đức Bà Paris","id":"Notre Dame de Paris","ms":"Katedral Notre-Dame","fil":"Notre-Dame","ur":"نوٹر ڈیم ڈے پیرس","ta":"நோட்ரே டேம் டி பாரிஸ்"},"lat":48.853,"lon":2.3498,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Notre-Dame_de_Paris_2013-07-24.jpg/960px-Notre-Dame_de_Paris_2013-07-24.jpg","page":"https://commons.wikimedia.org/wiki/File:Notre-Dame_de_Paris_2013-07-24.jpg","auteur":"P e z i","licence":"CC BY-SA 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2981"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Cath%C3%A9drale_Notre-Dame_de_Paris"}],"recupere":"2026-11-14","court":{"fr":"cathédrale située à Paris, en France","en":"cathedral in Paris","es":"catedral católica en París, Francia","de":"Kathedrale und Sitz des Erzbistums Paris","it":"cattedrale cattolica dell'arcidiocesi di Parigi","pt":"catedral francesa","nl":"kathedraal in Parijs, Frankrijk","pl":"świątynia katolicka we Francji, w Paryżu; archikatedra w stylu gotyckim","ru":"готический католический собор в Париже","uk":"собор у Парижі","ar":"كاتدرائية في باريس","he":"קתדרלה גותית בפריז, צרפת","tr":"Paris'teki katedral","el":"καθεδρικός ναός στο Παρίσι της Γαλλίας","sv":"katedral i Paris, Frankrike","da":"katedral i Paris","nb":"katedral i Paris, Frankrike","fi":"katedraali Pariisissa","cs":"katedrála v Paříži","sk":"katedrála v Paríži","hu":"párizsi katedrális","ro":"catedrală catolică din Paris, Franța","sl":"stolna cerkev nadškofije v Parizu (Francija)","lv":"katedrāle Parīzē, Francijā","et":"kirik Pariisis","ca":"catedral de l'arxidiòcesi de París","eu":"Parisko katedral gotikoa","is":"Dómkirkja í París","sq":"Katedrale","mk":"катедрала во Париз","zh-CN":"天主教巴黎總教區的主教座堂","zh-TW":"天主教巴黎總教區的主教座堂","ja":"パリの大聖堂","ko":"프랑스 파리에 있는 고딕 양식의 성당","fa":"یکی از معروف‌ترین کلیساهای دنیا","th":"อาสนวิหารในกรุงปารีส","id":"gereja di Prancis","fil":"Katedral sa Pari"},"long":{"ru":"Собо́р Пари́жской Богома́тери, также Парижский собор Нотр-Да́м или Нотр-Да́м-де-Пари́ — католический храм в центре Парижа, один из символов французской столицы. Кафедральный собор архиепархии Парижа. Расположен в восточной части острова Сите, в 4-м городском округе, на месте первой христианской церкви Парижа — базилики Святого Стефана, построенной, в свою очередь, на фундаменте галло-римского храма Юпитера. Собор представляет собой памятник архитектуры ранней французской готики. Собор возводили по инициативе парижского епископа Мориса де Сюлли в период 1163—1345 годов.","pt":"A Catedral de Notre-Dame de Paris é uma das mais antigas catedrais francesas em estilo gótico. Iniciada sua construção no ano de 1163, é dedicada à Virgem Maria e situa-se na Île de la Cité em Paris, rodeada pelas águas do rio Sena.","nl":"De Notre-Dame van Parijs is een in vroeggotische stijl opgetrokken kathedraal op het Île de la Cité, in het centrum van Parijs, gewijd aan de heilige maagd Maria.","pl":"Notre-Dame de Paris – gotycka archikatedra w Paryżu. Jedna z najbardziej znanych katedr na świecie, między innymi dzięki powieści Katedra Marii Panny w Paryżu francuskiego pisarza Victora Hugo. Jej nazwa oznacza Naszą Panią i odnosi się do Marii, Matki Bożej.","ja":"パリのノートルダム大聖堂 は、フランス・パリのシテ島にあるローマ・カトリック教会の大聖堂、パリ司教座聖堂である。","ko":"파리 노트르담 대성당(프랑스어: cathédrale Notre-Dame de Paris 카테드랄 노트르담 드 파리[*])은 프랑스 파리 시테 섬 동쪽 반쪽에 있는 프랑스 후기 고딕 양식의 성당이다. 이 대성당은 지금도 로마 가톨릭교회의 교회 건물로서 파리 대주교좌 성당으로 사용되고 있다. 노트르담 대성당은 흔히 프랑스 고딕 건축의 정수로 이야기된다. 이 대성당은 프랑스의 유명한 건축가인 비올레르뒤크에 의해 파괴된 상태에서 복구되었다. “노트르담”은 “우리의 귀부인”이라는 뜻의 프랑스어다(성모 마리아를 의미함).","ar":"كاتدرائية سيدة باريس وتعني بالعربيَّة \"سيدة باريس\"، وهي كاتدرائية كاثوليكية قرطوسيَّة، ومقر أبرشية باريس تقع في الجانب الشرقي من جزيرة المدينة على نهر السين وفي الدائرة الرابعة في باريس أي في قلب باريس التاريخي .تعد الكاتدرائية واحدة من أفضل الأمثلة على فن العمارة القوطية الفرنسية. وتتميز عن الطراز الروماني القديم باستخدامها المبتكر للقبو في الأضلاع والدعامة الطائرة، ونوافذها الوردية الهائلة والملونة، والواقعيَّة ووفرة زخارفها النحتية. تشمل المكونات الرئيسية التي تميز كاتدرائية سيدة باريس الأورغن التاريخي الكبير وأجراسها الكنسية الهائلة.","zh-CN":"巴黎圣母院，正式名称为巴黎圣母主教座堂，是位于法国巴黎第四区西岱岛的天主教会教堂，也是天主教巴黎总教区的主教座堂，约建造于1163年到1250年间，属于哥特式建筑，是法兰西岛地区的哥特式教堂群中具有代表意义的一座，并以其开创性地使用的尖肋骨拱和飞扶壁，巨大而多彩的玫瑰窗，以及丰富雕塑而闻名。其为巴黎代表性的历史古迹、观光名胜与宗教场所更是法国最广为人知的象征之一，每年约有1,200万人次参观，使其成为巴黎最多人访问的观光景点。","zh-TW":"巴黎聖母院，正式名稱為巴黎聖母主教座堂，是位於法國巴黎第四區西堤島的天主教會教堂，也是天主教巴黎總教區的主教座堂，約建造於1163年到1250年間，屬於哥德式建築，是法蘭西島地區的哥德式教堂群中具有代表意義的一座，並以其開創性地使用的尖肋骨拱和飛扶壁，巨大而多彩的玫瑰窗，以及豐富雕塑而聞名。其為巴黎代表性的歷史古蹟、觀光名勝與宗教場所更是法國最廣為人知的象徵之一，每年約有1,200萬人次參觀，使其成為巴黎最多人造訪的觀光景點。","en":"Notre-Dame de Paris, often referred to simply as Notre-Dame, is a medieval Catholic cathedral and basilica on the Île de la Cité, in the 4th arrondissement of Paris, France. It is the cathedral church of the Roman Catholic Archdiocese of Paris.","es":"La catedral de Notre Dame es una catedral de culto católico, sede de la arquidiócesis de París, la capital de Francia. Dedicada a la Virgen María, en su advocación de Nuestra Señora de París, se sitúa en la pequeña isla de la Cité, rodeada por las aguas del río Sena. Es uno de los monumentos más populares de la capital francesa.","de":"Die Kathedrale Notre-Dame de Paris, umgangssprachlich kurz Notre-Dame, ist die römisch-katholische Bischofskirche der Erzdiözese Paris. Die unter dem Patrozinium Unserer Lieben Frau, also der Gottesmutter Maria, stehende Kirche wurde zwischen 1163 und 1345 errichtet und ist eines der frühesten gotischen Gotteshäuser Frankreichs. Ihre charakteristische Silhouette prägt das historische Zentrum von Paris auf der Île de la Cité im 4. Pariser Arrondissement.","fr":"La cathédrale Notre-Dame de Paris, communément appelée Notre-Dame, est l'un des monuments les plus emblématiques de Paris et de France. Située sur l'île de la Cité, dans le 4e arrondissement de la capitale, elle constitue un lieu de culte catholique et sert de siège à l'archidiocèse de Paris, dédié à la Vierge Marie.","it":"La cattedrale di Notre-Dame è il principale luogo di culto cattolico di Parigi, chiesa madre dell'arcidiocesi di Parigi."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%A1%D0%BE%D0%B1%D0%BE%D1%80_%D0%9F%D0%B0%D1%80%D0%B8%D0%B6%D1%81%D0%BA%D0%BE%D0%B9_%D0%91%D0%BE%D0%B3%D0%BE%D0%BC%D0%B0%D1%82%D0%B5%D1%80%D0%B8","pt":"https://pt.wikipedia.org/wiki/Catedral_de_Notre-Dame_de_Paris","nl":"https://nl.wikipedia.org/wiki/Notre-Dame_van_Parijs","pl":"https://pl.wikipedia.org/wiki/Katedra_Notre-Dame_w_Pary%C5%BCu","ja":"https://ja.wikipedia.org/wiki/%E3%83%8E%E3%83%BC%E3%83%88%E3%83%AB%E3%83%80%E3%83%A0%E5%A4%A7%E8%81%96%E5%A0%82_(%E3%83%91%E3%83%AA)","ko":"https://ko.wikipedia.org/wiki/%EB%85%B8%ED%8A%B8%EB%A5%B4%EB%8B%B4_%EB%8C%80%EC%84%B1%EB%8B%B9","ar":"https://ar.wikipedia.org/wiki/%D9%83%D8%A7%D8%AA%D8%AF%D8%B1%D8%A7%D8%A6%D9%8A%D8%A9_%D8%B3%D9%8A%D8%AF%D8%A9_%D8%A8%D8%A7%D8%B1%D9%8A%D8%B3","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E8%81%96%E6%AF%8D%E9%99%A2","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E8%81%96%E6%AF%8D%E9%99%A2","en":"https://en.wikipedia.org/wiki/Notre-Dame_de_Paris","es":"https://es.wikipedia.org/wiki/Catedral_de_Notre_Dame_de_Par%C3%ADs","de":"https://de.wikipedia.org/wiki/Kathedrale_Notre-Dame_de_Paris","fr":"https://fr.wikipedia.org/wiki/Cath%C3%A9drale_Notre-Dame_de_Paris","it":"https://it.wikipedia.org/wiki/Cattedrale_di_Notre-Dame"},"site":"https://www.notredamedeparis.fr/en/","adresse":"Place du Parvis de Notre-Dame 6"},{"id":"wd-Q23402","cat":"musees","ville":"paris","nom":{"fr":"Musée d'Orsay","en":"Musée d'Orsay","es":"Museo de Orsay","de":"Musée d’Orsay","it":"Museo d'Orsay","pt":"Museu de Orsay","nl":"Musée d'Orsay","pl":"Musée d’Orsay","ru":"Музей Орсе","uk":"Музей д'Орсе","ar":"متحف أورسي","he":"מוזיאון ד'אורסה","tr":"Musée d'Orsay","el":"Μουσείο Ορσέ","sv":"Musée d’Orsay","da":"Musée d'Orsay","nb":"Musée d'Orsay","fi":"Musée d’Orsay","cs":"Muzeum Orsay","sk":"Musée d’Orsay","hu":"Musée d’Orsay","ro":"Musée d'Orsay","bg":"Музей Орсе","hr":"Muzej d'Orsay","sr":"Музеј Орсеј","sl":"Orsayjski muzej","lt":"Orsė muziejus","lv":"Orsē muzejs","et":"Orsay muuseum","ca":"Museu d'Orsay","eu":"Orsay museoa","is":"Orsay-minjasafnið","ga":"Musée d'Orsay","sq":"Musée d'Orsay","mk":"Музеј Орсе","zh-CN":"奥赛博物馆","ja":"オルセー美術館","ko":"오르세 미술관","hi":"ओर्से संग्रहालय","bn":"মুজে দর্সে","fa":"موزه اورسی","th":"พิพิธภัณฑ์ออร์แซ","vi":"Bảo tàng Orsay","id":"Museum Orsay","ms":"Muzium Orsay","fil":"Museo ng Orsay","sw":"Musée d'Orsay","ur":"Musée d'Orsay","ta":"ஓர்சே அருங்காட்சியகம்"},"lat":48.859972,"lon":2.326527,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Gare_d%27Orsay_%2849570190081%29.jpg/960px-Gare_d%27Orsay_%2849570190081%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Gare_d%27Orsay_(49570190081).jpg","auteur":"Cheng-en Cheng from Taichung City, Taiwan","licence":"CC BY-SA 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q23402"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_d'Orsay"}],"recupere":"2026-11-14","court":{"fr":"musée de Paris, France","en":"art museum in Paris, France","es":"pinacoteca que se encuentra en París, Francia","de":"Kunstmuseum in Paris","it":"museo di Parigi, Francia","pt":"museu na cidade de Paris","nl":"museum in Parijs","pl":"muzeum sztuki w Paryżu we Francji","ru":"музей изобразительных искусств в Париже, одно из крупнейших в мире собраний европейской живописи и скульптуры 1850—1910 гг.","uk":"художній музей у Парижі","ar":"متحف فني","he":"מוזיאון בצרפת","tr":"Paris'te sanat müzesi","sv":"konstmuseum i Paris","da":"kunstmuseum i Paris","nb":"kunstmuseum i Paris","fi":"museo Ranskassa","cs":"muzeum v Paříži","hu":"művészeti múzeum Párizsban, Franciaországban","ro":"muzeu de artă din Paris, Franța","sr":"музеј у Француској","sl":"umetnostni muzej v Parizu (Francija)","lv":"mākslas muzejs Parīzē","ca":"museu d'art a París, França","is":"listasafn í París í Frakklandi","sq":"muze i arteve","zh-CN":"法國巴黎的藝術博物館","ja":"パリの美術館","ko":"프랑스 파리의 미술관","th":"พิพิธภัณฑ์ศิลปะ, ปารีส","vi":"bảo tàng nghệ thuật ở Paris, Pháp","id":"museum pertunjukan seni di Perancis"},"long":{"pt":"O Museu de Orsay é um museu na cidade de Paris, na França. Situa-se na margem esquerda do rio Sena no 7.º arrondissement. As colecções do museu apresentam principalmente pinturas e esculturas da arte ocidental do período compreendido entre 1848 e 1914. Entre outras, estão aí presentes obras de Van Gogh, Cézanne, Degas, Maurice Denis, Odilon Redon. Existem também exposições temporárias que ocorrem paralelamente à exposição permanente.","pl":"Muzeum Orsay – muzeum w Paryżu, położone na lewym brzegu Sekwany. Zbiory zawierają głównie sztukę francuską z lat 1848–1918: malarstwo, rzeźbę, fotografię oraz meble. Dzieła te są młodsze od tych, które prezentowane są w Luwrze, a starsze od zbiorów Centre Georges Pompidou. Rocznie muzeum odwiedza ok. 4 miliony zwiedzających. Najbliższą stacją metra jest Solférino.","ru":"Орсе́, или Орсэ, музей Орсе — музей изобразительных искусств в Париже, на левом берегу Сены; одно из крупнейших в мире собраний европейской живописи и скульптуры периода 1850—1910 гг. Третий по популярности музей столицы Франции и десятый — в мире. Основу коллекции составляют работы импрессионистов и постимпрессионистов. Коллекция также богата произведениями декоративного искусства в стиле ар-нуво, фотографиями и предметами архитектуры. Музей Орсе является одним из крупнейших художественных музеев Европы. В 2019 году музей посетило более 3,6 миллиона человек.","nl":"Het Musée d'Orsay in Parijs is een kunstmuseum dat de geschiedenis van de westerse kunst tussen 1848 en 1914 bestrijkt, met een sterk accent op de 19e-eeuwse Franse kunst. Het museum bezit een vermaarde verzameling impressionistische werken. Ook herbergt het museum beeldhouwkunst en toegepaste kunst. Het museum maakt deel uit van de Réunion des musées nationaux et du Grand Palais des Champs-Élysées.","zh-CN":"奥赛博物馆 是一座位于法国巴黎的近代国家艺术博物馆，于1986年12月9日正式开放。","ja":"オルセー美術館 は、フランスのパリにある19世紀美術専門の美術館である。印象派の画家の作品が数多く収蔵されていることで有名。","ko":"오르세 미술관(,, 프랑스어 발음: ​[myze dɔʁsɛ]; 영어: Orsay Museum)은 프랑스 파리의 센강 좌안에 있는 박물관이다. 1898년부터 1900년까지 건설된 보자르 양식의 옛 오르세역 건물에 자리하고 있다. 이 미술관은 주로 1848년부터 1914년까지의 프랑스 미술 작품(프랑스에서 활동했던 외국 예술가들의 작품 포함)을 소장하고 있으며, 회화, 조각, 가구, 사진 등을 전시하고 있다. 베르트 모리조, 클로드 모네, 에두아르 마네, 에드가 드가, 오귀스트 르누아르, 폴 세잔, 조르주 쇠라, 알프레드 시슬레, 폴 고갱, 빈센트 반 고흐 등의 화가들의 인상주의와 후기인상주의 걸작을 세계에서 가장 많이 소장하고 있다. 이 작품들 중 상당수는 1986년 미술관 개관 이전에 죄드폼 국립미술관에 소장되어 있었던 것을 이관받은 것이다. 유럽에서 가장 큰 미술관 중 하나이다.","ar":"متحف أورسي. هو متحف في باريس بفرنسا على الضفة الغربية لنهر السين. ومقره محطة سابقة للسكة الحديد في العاصمة الفرنسية وهي محطة Gare d'Orsay. يحوي المتحف في معظمه أعمال من الفن الفرنسي. تؤرخ منذ 1848 حتى 1915 بما فيها لوحات، منحوتات، أثاث وصور الفن الرفيع الفوتوغرافية. ولعل أشهر مايحويه النفائس والقطع النادرة للوحات الفن الانطباعي لفنانين من المشاهير أمثال كلود مونيه ورونوار. العديد من هذه اللوحات تم عرضها أولا في Galerie nationale du Jeu de Paume سابقا لافتتاح المتحف في 1986.","zh-TW":"奧賽博物館 是一座位於法國巴黎的近代國家藝術博物館，於1986年12月9日正式開放。","en":"The Musée d'Orsay is a museum in Paris, France, on the Left Bank of the Seine. One of the largest art museums in Europe, it is housed in the former Gare d'Orsay, a Beaux-Arts railway station built from 1898 to 1900. The museum holds mainly French artworks dating from 1848 to 1914, including paintings, sculptures, furniture, and photography. It houses the largest collection of Impressionist and post-Impressionist masterpieces in the world, by painters such as Monet, Manet, Renoir, Morisot, Degas, Sisley, Cézanne, Seurat, Gauguin, and van Gogh.","fr":"Le musée d'Orsay est un musée parisien situé dans le 7e arrondissement, le long de la rive gauche de la Seine, en surplomb de la promenade Édouard-Glissant.","es":"El Museo de Orsay es una pinacoteca ubicada en París (Francia) dedicada a las artes plásticas del siglo XIX y, más en concreto, del periodo 1848-1914. Ocupa el antiguo edificio de la estación ferroviaria de Orsay.","de":"Das Musée d’Orsay ist ein Kunstmuseum im Quartier Saint-Thomas-d’Aquin des 7. Arrondissements von Paris. Es liegt am südlichen Ufer der Seine gegenüber dem Tuileriengarten. Das Gebäude war ursprünglich als Gare d’Orsay einer der Pariser Fernbahnhöfe. Dieser war anlässlich der Weltausstellung des Jahres 1900 von Victor Laloux erbaut worden und wurde bis 1939 für den Fernverkehr in den Südwesten Frankreichs genutzt.","it":"Il Museo d'Orsay è un museo che si trova in Francia a Parigi, in Rue de la Légion d'Honneur, 1."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Museu_de_Orsay","pl":"https://pl.wikipedia.org/wiki/Mus%C3%A9e_d%E2%80%99Orsay","ru":"https://ru.wikipedia.org/wiki/%D0%9C%D1%83%D0%B7%D0%B5%D0%B9_%D0%9E%D1%80%D1%81%D0%B5","nl":"https://nl.wikipedia.org/wiki/Mus%C3%A9e_d'Orsay","zh-CN":"https://zh.wikipedia.org/wiki/%E5%A5%A5%E8%B5%9B%E5%8D%9A%E7%89%A9%E9%A6%86","ja":"https://ja.wikipedia.org/wiki/%E3%82%AA%E3%83%AB%E3%82%BB%E3%83%BC%E7%BE%8E%E8%A1%93%E9%A4%A8","ko":"https://ko.wikipedia.org/wiki/%EC%98%A4%EB%A5%B4%EC%84%B8_%EB%AF%B8%EC%88%A0%EA%B4%80","ar":"https://ar.wikipedia.org/wiki/%D9%85%D8%AA%D8%AD%D9%81_%D8%A3%D9%88%D8%B1%D8%B3%D9%8A","zh-TW":"https://zh.wikipedia.org/wiki/%E5%A5%A5%E8%B5%9B%E5%8D%9A%E7%89%A9%E9%A6%86","en":"https://en.wikipedia.org/wiki/Mus%C3%A9e_d'Orsay","fr":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_d'Orsay","es":"https://es.wikipedia.org/wiki/Museo_de_Orsay","de":"https://de.wikipedia.org/wiki/Mus%C3%A9e_d%E2%80%99Orsay","it":"https://it.wikipedia.org/wiki/Museo_d'Orsay"},"site":"https://www.musee-orsay.fr"},{"id":"wd-Q187840","cat":"culture","ville":"paris","nom":{"fr":"Palais Garnier","en":"Palais Garnier","es":"Ópera Garnier","de":"Opéra Garnier","it":"Opéra Garnier","pt":"Ópera Garnier","nl":"Opéra Garnier","pl":"Opéra Garnier","ru":"Опера Гарнье","uk":"Опера Гарньє","ar":"قصر غارنييه","he":"האופרה גרנייה","tr":"Palais Garnier","el":"Όπερα Γκαρνιέ","sv":"L'Opéra Garnier","da":"Opéra Garnier","nb":"Opéra Garnier","fi":"Palais Garnier","cs":"Opéra Garnier","sk":"Palais Garnier","hu":"Opéra Garnier","ro":"Opéra Garnier","bg":"Пале Гарние","hr":"Opera Garnier","sr":"Опера Гарније","sl":"Opéra Garnier","lt":"Garnjė rūmai","et":"Palais Garnier","ca":"Òpera Garnier","eu":"Opéra Garnier","mk":"Опера Гарние","zh-CN":"巴黎歌剧院","zh-TW":"巴黎歌劇院","ja":"ガルニエ宮","ko":"오페라 가르니에","hi":"पाले गार्निये","bn":"পালে গার্নিয়ে","fa":"کاخ گارنیه","th":"โรงอุปรากรปาแลการ์นีเย","vi":"Nhà hát Opéra Garnier","id":"Palais Garnier","ms":"Palais Garnier","ur":"گارنیئر محل"},"lat":48.871944,"lon":2.331667,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Paris_Palais_Garnier_2010-04-06_16.55.07.jpg/960px-Paris_Palais_Garnier_2010-04-06_16.55.07.jpg","page":"https://commons.wikimedia.org/wiki/File:Paris_Palais_Garnier_2010-04-06_16.55.07.jpg","auteur":"Alexander Hoernigk","licence":"CC BY 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q187840"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Op%C3%A9ra_Garnier"},{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/cfeee329-7fce-31d8-bc15-9842d9bc5568"}],"recupere":"2026-11-14","court":{"fr":"salle d'opéra française","en":"opera house in Paris, France","es":"teatro de ópera en París, Francia","de":"Opernhaus in Paris","it":"teatro storico di Parigi, Francia (1875)","pt":"teatro fundado em 1669 por Luís XIV","nl":"bouwwerk in Parijs","pl":"gmach opery (Paryż, Francja)","ru":"театр в Париже","ar":"متحف في فرنسا","he":"בית אופרה מפואר בפריז, צרפת","el":"όπερα στο Παρίσι","fi":"oopperatalo Pariisissa","cs":"operní dům v Paříži","hu":"Párizs egyik operaháza","bg":"опера в Париж","hr":"operna kuća u Parizu","sr":"оперски театар који се налази у Паризу","sl":"operna hiša v Parizu (Francija)","zh-CN":"在法國巴黎的歌劇院","ja":"パリの歌劇場","ko":"프랑스 파리 9구에 위치한 오페라 극장","vi":"nhà hát ở Paris, Pháp","id":"salah satu teater di Prancis"},"long":{"pt":"A Ópera Garnier ou Palais Garnier é uma casa de ópera localizada no IX arrondissement de Paris, França. O edifício é considerado uma das obras-primas da arquitetura de seu tempo. Construído em estilo neobarroco, é o 13º teatro a hospedar a Ópera de Paris, desde sua fundação por Luís XIV, em 1669. Sua capacidade é de 1979 espectadores sentados.","nl":"De Opéra Garnier, ook wel Palais Garnier genoemd, is een operagebouw in Parijs. Het ligt in het 9e arrondissement aan de Place de l'Opéra (Operaplein) en is een van de opvallendste gebouwen van de Franse hoofdstad. Het is de thuisbasis van het oudste opera- en balletgezelschap van Frankrijk, de Opéra national de Paris.","pl":"Opéra Garnier, Palais Garnier – gmach opery w Paryżu przeznaczony dla 2200 osób, wybudowany w stylu eklektycznym w latach 70. XIX w. według projektu Charles’a Garniera. Od otwarcia w 1875 do wybudowania Opéra Bastille siedziba Narodowej Opery Paryża, zaś od przeniesienia się zespołu do nowego obiektu nosi nazwę Palais Garnier, chociaż na fasadzie nadal widnieje stary napis Académie Nationale de Musique.","ru":"Пари́жская о́пера, то же, что Гранд-опера́, в современной Франции известна как Опера́ Гарнье́ — театр в Париже, один из самых известных и значимых театров оперы и балета в мире.","ja":"ガルニエ宮 は、フランスの首都パリにある歌劇場である。単にオペラ座（l'Opéra）と呼ばれることもある。パリ国立オペラの公演会場の一つである。","ko":"오페라 가르니에(Opéra Garnier) 또는 가르니에 궁(Palais Garnier)은 프랑스 파리 9구 오페라 광장 북쪽 끝에 위치한 2200석을 수용하는 오페라 극장이다. 파리 오페라 극장(Opéra de Paris, Paris Opéra)으로도 알려져 있다. 샤를 가르니에가 신바로크 양식으로 설계한 건물로 그 당시 건축학적 걸작 중 하나로 평가된다.","ar":"قصر غارنييه يسمى أيضا أوبرا غارنييه ‏. يحتوي على 1600 مقعد ويقع في ميدان الأوبرا في باريس بفرنسا. كان المقر الرئيسي لفرقة أوبرا باريس من عام 1875 حتى عام 1989.","zh-CN":"加尼叶宫，又称加尼叶歌剧院，常称为巴黎歌剧院，是一座位于法国巴黎第九区歌剧院广场的歌剧院，在拿破仑三世皇帝的授意下于1861至1875年间建造，并由建筑师夏尔·加尼叶所设计。","zh-TW":"加尼葉宮，又稱加尼葉歌劇院，常稱為巴黎歌劇院，是一座位於法國巴黎第九區歌劇院廣場的歌劇院，在拿破崙三世皇帝的授意下於1861至1875年間建造，並由建築師夏爾·加尼葉所設計。","en":"The Palais Garnier, also known as Opéra Garnier, is a historic 1,979-seat opera house at the Place de l'Opéra in the 9th arrondissement of Paris, France. It was built for the Paris Opera from 1861 to 1875 at the behest of Emperor Napoleon III. Initially referred to as le nouvel Opéra de Paris, it soon became known as the Palais Garnier, \"in acknowledgment of its extraordinary opulence\" and the architect Charles Garnier's plans and designs, which are representative of the Napoleon III style.","fr":"L'opéra Garnier, ou palais Garnier, est un théâtre national qui a la vocation d'être une académie de musique, de chorégraphie et de poésie lyrique ; il est un élément majeur du patrimoine du 9e arrondissement de Paris et de la capitale. Il est situé place de l'Opéra, à l'extrémité nord de l'avenue de l'Opéra et au carrefour de nombreuses voies.","de":"Die Opéra Garnier, auch Palais Garnier genannt, ist eines der zwei Pariser Opernhäuser, die der staatlichen Institution Opéra National de Paris unterstehen. Sie wurde 1875 eröffnet und steht am rechten Seineufer im 9. Arrondissement. Sie ist nach ihrem Architekten Charles Garnier benannt. Seit der Eröffnung der Opéra Bastille im Jahre 1989 wird die Opéra Garnier hauptsächlich für Ballettaufführungen des hauseigenen Ballet de l’Opéra de Paris genutzt, führt aber nach wie vor auch klassische Opern auf.","es":"La Ópera Garnier, Palacio Garnier u Ópera de París, es uno de los edificios más característicos del IX Distrito de París y del paisaje urbano de la capital francesa. Napoleón III ordenó su construcción al arquitecto Charles Garnier, quien lo diseñó en Estilo Segundo Imperio o Napoleón III.","it":"L'Opéra Garnier, o Palais Garnier, è un teatro d'opera situato nel IX arrondissement di Parigi, fino al 1989 primo teatro della capitale francese nonché sede del Balletto dell'opera di Parigi, successivamente, dopo l'inaugurazione dell'Opéra Bastille, è diventato parte dell'Opéra national de Paris che lo utilizza principalmente per rappresentazioni di danza e opere barocche. Il teatro Garnier dal 16 ottobre 1923 è monumento storico di Francia."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/%C3%93pera_Garnier","nl":"https://nl.wikipedia.org/wiki/Op%C3%A9ra_Garnier","pl":"https://pl.wikipedia.org/wiki/Op%C3%A9ra_Garnier","ru":"https://ru.wikipedia.org/wiki/%D0%9E%D0%BF%D0%B5%D1%80%D0%B0_%D0%93%D0%B0%D1%80%D0%BD%D1%8C%D0%B5","ja":"https://ja.wikipedia.org/wiki/%E3%82%AC%E3%83%AB%E3%83%8B%E3%82%A8%E5%AE%AE","ko":"https://ko.wikipedia.org/wiki/%EC%98%A4%ED%8E%98%EB%9D%BC_%EA%B0%80%EB%A5%B4%EB%8B%88%EC%97%90","ar":"https://ar.wikipedia.org/wiki/%D9%82%D8%B5%D8%B1_%D8%BA%D8%A7%D8%B1%D9%86%D9%8A%D9%8A%D9%87","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E6%AD%8C%E5%8A%87%E9%99%A2","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E6%AD%8C%E5%8A%87%E9%99%A2","en":"https://en.wikipedia.org/wiki/Palais_Garnier","fr":"https://fr.wikipedia.org/wiki/Op%C3%A9ra_Garnier","de":"https://de.wikipedia.org/wiki/Op%C3%A9ra_Garnier","es":"https://es.wikipedia.org/wiki/%C3%93pera_Garnier","it":"https://it.wikipedia.org/wiki/Op%C3%A9ra_Garnier"},"site":"https://www.operadeparis.fr/","adresse":"Place de l'Opéra, 75009 Paris, France"},{"id":"wd-Q189503","cat":"patrimoine","ville":"paris","nom":{"fr":"Place de la Concorde","en":"Place de la Concorde","es":"Plaza de la Concordia","de":"Place de la Concorde","it":"Place de la Concorde","pt":"Praça da Concórdia","nl":"Place de la Concorde","pl":"Place de la Concorde","ru":"Площадь Согласия","uk":"Площа Згоди","ar":"ميدان الكونكورد","he":"כיכר הקונקורד","tr":"Concorde Meydanı","el":"Πλατεία Κονκόρντ","sv":"Place de la Concorde","da":"Place de la Concorde","nb":"Place de la Concorde","fi":"Place de la Concorde","cs":"Place de la Concorde","sk":"Place de la Concorde","hu":"Concorde tér","ro":"Place de la Concorde","bg":"Конкорд","hr":"Trg sloge","sr":"Трг Конкорд","sl":"Place de la Concorde","lt":"Santarvės aikštė","lv":"Konkordijas laukums","et":"Concorde'i väljak","ca":"Plaça de la Concorde","eu":"Concorde plaza","ga":"Place de la Concorde","mk":"Конкорд","zh-CN":"协和广场","zh-TW":"協和廣場","ja":"コンコルド広場","ko":"콩코르드 광장","hi":"प्लास द ला कोंकोर्द","fa":"میدان کنکورد","th":"ปลัสเดอลากงกอร์ด","vi":"Quảng trường Concorde","id":"Place de la Concorde","ms":"Place de la Concorde","ur":"پلیس دے لا کونکارد"},"lat":48.865633,"lon":2.321236,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Place_de_la_Concorde_from_the_Eiffel_Tower%2C_Paris_April_2011.jpg/960px-Place_de_la_Concorde_from_the_Eiffel_Tower%2C_Paris_April_2011.jpg","page":"https://commons.wikimedia.org/wiki/File:Place_de_la_Concorde_from_the_Eiffel_Tower,_Paris_April_2011.jpg","auteur":"Cristian Bortes from Cluj-Napoca, Romania","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q189503"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Place_de_la_Concorde"}],"recupere":"2026-11-14","court":{"fr":"place de Paris, en France","en":"square in the 8th arrondissement of Paris, France","es":"plaza en París, Francia","de":"Platz in Paris‎","it":"Piazza a Parigi, Francia","pt":"Praça pública em Paris, França","nl":"plein in het 8e arrondissement van Parijs, Frankrijk","pl":"Plac w Paryżu (Francja)","ru":"площадь в центре Парижа, столицы Франции","uk":"площа в центрі Парижу, столиці Франції","ar":"ميدان في فرنسا","he":"כיכר בפריז, צרפת","tr":"Paris'te meydan","el":"πλατεία στο Παρίσι","sv":"torg i Paris, Frankrike","da":"plads i Paris","fi":"aukio Pariisissa","cs":"náměstí v Paříži","hu":"csomópont Párizs északi felén, közel a Szajnához","sr":"највећи трг Париза","sl":"trg v 8. okrožju Pariza (Francija)","lv":"laukums Parīzē, Francijā","mk":"плоштад во Париз","zh-CN":"法国巴黎的广场","ja":"パリの広場","fa":"یک میدان در پاریس، فرانسه","vi":"quảng trường ở Paris, Pháp","id":"alun-alun di Paris, Prancis"},"long":{"pt":"A Praça da Concórdia situa-se ao pé da Avenida dos Campos Elísios (Champs-Élysées), no VIII arrondissement de Paris, na França. É a maior da capital francesa e a segunda do país, atrás da Praça dos Quinconces, em Bordéus. É famosa por ser palco de acontecimentos marcantes da história da França.","nl":"De Place de la Concorde (\"Eendrachtsplein\") is een monumentaal plein in het centrum van de Franse hoofdstad Parijs, gelegen in het 8e arrondissement op de rechteroever van de Seine. Het plein beslaat ruim acht hectare en is daarmee het grootste plein van de stad. Samen met de Place Dauphine, de Place des Vosges, de Place des Victoires en de Place Vendôme is het een van de vijf koninklijke pleinen van Parijs. Het is in deze reeks het laatste plein dat tot stand kwam.","pl":"Place de la Concorde – duży plac w centrum Paryża, położony między Polami Elizejskimi a Ogrodami Tuileries.","ru":"Площадь Согласия — центральная площадь Парижа, выдающийся памятник градостроительства эпохи неоклассицизма. Находится в VIII округе Парижа на правом берегу Сены, в центре города между Елисейскими полями и садом Тюильри. Является второй по величине во Франции. Носила имя короля Людовика XV, поскольку её территория, находившаяся в собственности короля, была предоставлена городу королём Людовиком в 1743 году. После свержения монархии называлась Площадью Революции; современное наименование получила решением Директории 25 октября 1795 года в знак примирения сословий по окончании революционного террора.","ja":"コンコルド広場 は、フランス・パリ8区にある大広場。パリのセーヌ川右岸（北岸）の中心部界隈に位置し、テュイルリー庭園と、同広場が起点となるシャンゼリゼ通りとに挟まれた場所にある。同広場から東側に向かうとパリの行政区画上1区にあたる。2024年パリオリンピックではスケートボード、自転車のBMXフリースタイル、バスケットボールの3x3、ブレイキン、同パラリンピックでは開会式の会場として使用された。","ko":"콩코르드 광장(프랑스어: Place de la Concorde, 프랑스어 발음 )은 프랑스 파리의 광장으로 샹젤리제 거리 동쪽에 튈르리 공원과 사이에 위치한다. 면적은 86,400m2(8.64ha)로 파리에서는 가장 넓은 광장이다.","zh-CN":"协和广场，是法国巴黎市中心塞纳河右岸的一个大广场，面积约8.4万平方米，同时也是当前法国最大的广场及巴黎著名地标。","zh-TW":"協和廣場，是法國巴黎市中心塞納河右岸的一個大廣場，面積約8.4萬平方米，同時也是當前法國最大的廣場及巴黎著名地標。","ar":"ميدان الكونكورد يعد من أكبر ميادين باريس عاصمة فرنسا.يقع في قلب باريس في نهاية شارع الشانزلزيه (Champs-Élysées) من ناحيته الشرقية. تزينه مسلة مصرية ضخمة. فقد قام الفرنسيون بمجهودات كبيرة في الكشف عن أسرار الحضارة المصرية القديمة. وقد أهدت مصر فرنسا مسلتين من مسلات الملك رمسيس الثاني في معبد الأقصر.","it":"Place de la Concorde, in italiano Piazza della Concordia, è una piazza dell'VIII arrondissement di Parigi.","es":"La plaza de la Concordia está situada al comienzo de la avenida de los Campos Elíseos en el VIII Distrito de París, en Francia. Se trata de la segunda más grande de Francia después de la plaza de Quinconces, en Burdeos.","fr":"La place de la Concorde, initialement appelée place Louis XV puis place de la Révolution de 1792 à 1795, qui s’étend sur 7,56 hectares, est la plus grande place de Paris. Elle est située dans le 8e arrondissement.","de":"Die Place de la Concorde [plas də la kɔ̃kɔʁd] ist mit 7,56 ha der größte Platz von Paris. Er liegt nördlich der Seine im 8. Arrondissement zwischen Jardin des Tuileries und Avenue des Champs-Élysées.","en":"The Place de la Concorde, originally the Place Louis XV, and later the Place Louis XVI, is a public square in Paris. Measuring 7.6 ha in area, it is the largest square in the city. It is located in the 8th arrondissement, at the eastern end of the Champs-Élysées."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Pra%C3%A7a_da_Conc%C3%B3rdia","nl":"https://nl.wikipedia.org/wiki/Place_de_la_Concorde","pl":"https://pl.wikipedia.org/wiki/Place_de_la_Concorde","ru":"https://ru.wikipedia.org/wiki/%D0%9F%D0%BB%D0%BE%D1%89%D0%B0%D0%B4%D1%8C_%D0%A1%D0%BE%D0%B3%D0%BB%D0%B0%D1%81%D0%B8%D1%8F","ja":"https://ja.wikipedia.org/wiki/%E3%82%B3%E3%83%B3%E3%82%B3%E3%83%AB%E3%83%89%E5%BA%83%E5%A0%B4","ko":"https://ko.wikipedia.org/wiki/%EC%BD%A9%EC%BD%94%EB%A5%B4%EB%93%9C_%EA%B4%91%EC%9E%A5","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8D%8F%E5%92%8C%E5%B9%BF%E5%9C%BA","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8D%8F%E5%92%8C%E5%B9%BF%E5%9C%BA","ar":"https://ar.wikipedia.org/wiki/%D9%85%D9%8A%D8%AF%D8%A7%D9%86_%D8%A7%D9%84%D9%83%D9%88%D9%86%D9%83%D9%88%D8%B1%D8%AF","it":"https://it.wikipedia.org/wiki/Place_de_la_Concorde","es":"https://es.wikipedia.org/wiki/Plaza_de_la_Concordia","fr":"https://fr.wikipedia.org/wiki/Place_de_la_Concorde","de":"https://de.wikipedia.org/wiki/Place_de_la_Concorde","en":"https://en.wikipedia.org/wiki/Place_de_la_Concorde"},"site":"https://www.pop.culture.gouv.fr/notice/merimee/PA00088880"},{"id":"wd-Q188856","cat":"patrimoine","ville":"paris","nom":{"fr":"Panthéon","en":"Panthéon","es":"Panteón de París","de":"Panthéon","it":"Pantheon","pt":"Panteão","nl":"Panthéon","pl":"Panteon w Paryżu","ru":"Пантеон","uk":"Пантеон","ar":"مقبرة العظماء","he":"הפנתאון של פריז","tr":"Panthéon","el":"Πάνθεον","sv":"Panthéon","da":"Panthéon","nb":"Panthéon","fi":"Panthéon","cs":"Pantheon","sk":"Panteón","hu":"Panthéon","ro":"Panthéon","bg":"Пантеон","hr":"Panteon u Parizu","sr":"Пантеон","sl":"Panteon","lt":"Panteonas","lv":"Panteons","et":"Panteon (Pariis)","ca":"Panteó de París","eu":"Parisko Panteoia","ga":"Panthéon","sq":"Panteoni, Paris","zh-CN":"先贤祠","zh-TW":"先賢祠","ja":"パンテオン","ko":"팡테옹","hi":"पाँतेओं","fa":"پانتئون","th":"ป็องเตอง","vi":"Điện Panthéon","id":"Panthéon","ms":"Panthéon, Paris","ur":"پانتھیون"},"lat":48.846198,"lon":2.346105,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Panth%C3%A9on%2C_Paris_25_March_2012.jpg/960px-Panth%C3%A9on%2C_Paris_25_March_2012.jpg","page":"https://commons.wikimedia.org/wiki/File:Panth%C3%A9on,_Paris_25_March_2012.jpg","auteur":"Camille Gévaudan","licence":"CC BY-SA 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q188856"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Panth%C3%A9on_(Paris)"}],"recupere":"2026-11-14","court":{"fr":"monument historique français","en":"mausoleum in Paris for the most distinguished French people","es":"monumento histórico francés","de":"Kirchengebäude und Grabstätte in Paris","it":"monumento di Parigi, Francia","pt":"igreja em França","nl":"gebouw in Parijs","pl":"mauzoleum wybitnych Francuzów","ru":"усыпальница выдающихся людей Франции","ar":"كنيسة في فرنسا","he":"צרפת","tr":"Fransa'da kilise","el":"κτίσμα στο Καρτιέ Λατέν στο Παρίσι","sv":"mausoleum i Paris","fi":"alkujaan Pyhän Genevièven kirkoksi vuonna 1789 valmistunut rakennus Pariisin Latinalaiskorttelissa","cs":"mauzoleum v Paříži","ro":"mausoleu din Paris pentru cei mai distinși francezi","lv":"ēka Parīzē, Francijā","ca":"mausoleu a París","sq":"kishë","ko":"프랑스 파리 라탱지구의 건축물","id":"bangunan kuil di Prancis"},"long":{"pt":"O Panteão de Paris é um mausoléu histórico, que combina elementos do estilo neoclássico e gótico, situado no monte de Santa Genoveva, no 5.º arrondissement de Paris, em pleno Quartier Latin, construído entre 1758 e 1790, a partir de projetos de Jacques-Germain Soufflot, a mando do rei Luís XV da França; o rei pretendia que fosse uma igreja dedicada a Santa Genoveva, padroeira de Paris, cujas relíquias seriam abrigadas na igreja. Nem Soufflot nem Luís XV viveram para ver a igreja concluída. Honra figuras notáveis como Voltaire, Rosseau, Marie Curie e Victor Hugo, que nele jazem.","nl":"Het Panthéon is een gebouw in het 5e arrondissement van de Franse hoofdstad Parijs. De architect Jacques Germain Soufflot bouwde het monument in de 18e eeuw oorspronkelijk als een kerk gewijd aan Genoveva van Parijs (Sainte-Geneviève); het is sinds de Franse Revolutie bekend als begraafplaats van beroemde Fransen. Soufflot wilde een klassiek gebouw realiseren met de lichtheid van een gotische kathedraal. Bij de bouw werden de open muren massiever uitgevoerd om structurele redenen.","pl":"Panteon – budowla w Dzielnicy Łacińskiej w Paryżu, wzniesiona pod koniec XVIII wieku jako kościół pod wezwaniem świętej Genowefy. Od 1885 roku pełni rolę mauzoleum wybitnych Francuzów.","ja":"パンテオン は、フランスのパリの5区、聖ジュヌヴィエーヴの丘に位置し、幅110メートル、奥行き84メートルのギリシア十字型の平面に大ドームとコリント式の円柱を持つ新古典主義建築の建築作品である。18世紀後半に、サント=ジュヌヴィエーヴ教会として建設され、後にフランスの偉人たちの遺体を祀る墓所・墓廟となった。「パンテオン」はもともとはギリシア語で「諸神の家」といったような意味であり、日本語では「万神殿」と訳される。","ru":"Пантео́н — архитектурно-исторический памятник, образец французского неоклассицизма в Латинском квартале 5-го округа Парижа, Франция. Первоначально церковь Святой Женевьевы, построенная по проекту архитектора Жак-Жермена Суффло в 1758—1790 годах. С 1791 года — Пантеон, усыпальница выдающихся людей Франции.","ar":"مقبرة العظماء أو البانثيون هي مبنى بالحي اللاتيني في باريس يضم رفات بعض عظماء الفرنسيين. تم بناؤه ليكون كنيسة لسانت جينيفيف، تقع في الدائرة الخامسة في باريس في مونتانيي سانت جانفيف. البانتيون يطل على كافة أرجاء باريس. كان مصممه جاك جيرمان لديه نية الجمع بين خفة وسطوع الكاتدرائية القوطية مع المبادئ الكلاسيكية.","zh-CN":"先贤祠 位于法国巴黎的拉丁区，最初是法王路易十五兴建的圣日内维耶大教堂，历经数次变迁以后现在成为法国最著名的文化名人安葬地。先贤祠是新古典主义建筑的早期典范，其立面仿照罗马万神殿（Pantheon），故又译为巴黎万神殿，拱顶为布拉曼特风格。","ko":"팡테옹(Panthéon 혹은 Panthéon de Paris)은 프랑스 파리 카르티에 라탱(Quartier latin) 지역에 있는 건축물이다. 입구에 있는 삼각형 부조 아래에는 \"조국이 위대한 사람들에게 사의를 표하다.\"(AUX GRANDS HOMMES LA PATRIE RECONNAISSANTE)라는 글자가 씌어 있는데, 팡테옹은 원래 성 주느비에브에게 봉헌된 교회였으나, 수많은 변화를 거쳐 현재는 예배 장소와 위인들의 묘지의 역할이 복합되었기 때문이다. 이 건물은 초기 신고전주의 건물로 파사드(Façade, 건물의 정면)은 로마의 판테온에서 따온 것으로 브라만테의 템피에토와 비슷하게 생긴 돔이 위에 얹혀 있다. 파리 5구에 위치한 팡테옹에서는 파리 전체를 내다볼 수 있다. 이 건물의 건축가인 자크 제르맹 수플로는 고딕 성당의 가벼움과 밝음을 고전적인 원리들과 복합하려는 의도를 갖고 있었다. 수플로는 자신의 작품이 완성되기 전에 사망하였고, 그의 설계안은 완전히 실행되지는 못하였다. 그가 이 걸작을 위해 계획한 건물의 투명성은 이뤄지지 못했다. 하지만, 이것은 당시의 중요한 건축적 성과들 중 하나였고, 최초의 기념비적인 신고전주의 건물이었다.","zh-TW":"先賢祠 位於法國巴黎的拉丁區，最初是法王路易十五興建的聖日內維耶大教堂，歷經數次變遷以後現在成為法國最著名的文化名人安葬地。先賢祠是新古典主義建築的早期典範，其立面仿照羅馬萬神殿（Pantheon），故又譯為巴黎萬神殿，拱頂為布拉曼特風格。","en":"The Panthéon is a monument in the 5th arrondissement of Paris, France. It stands in the Latin Quarter, on the Montagne Sainte-Geneviève, in the centre of the Place du Panthéon, which was named after it. The edifice was built between 1758 and 1790, from designs by Jacques-Germain Soufflot, at the behest of King Louis XV; the king intended it as a church dedicated to Saint Genevieve, Paris's patron saint, whose relics were to be housed in the church. Neither Soufflot nor Louis XV lived to see the church completed.","fr":"Le Panthéon de Paris est un monument situé dans le 5e arrondissement, servant de nécropole nationale où sont inhumées des personnalités ayant marqué l’histoire de la France.","it":"Il Pantheon di Parigi, eretto come chiesa cattolica dedicata a Sainte-Geneviève, è un monumento situato nella capitale francese nel cuore del quartiere latino, in cima al colle di Sainte-Geneviève. È alto in tutto 106 metri. È circondato dalla chiesa Saint-Étienne-du-Mont, dalla biblioteca Sainte-Geneviève, dalla Sorbona e da altri edifici monumentali. Particolarmente suggestiva è la vista da rue Soufflot, vicino ai giardini del Lussemburgo.","es":"El Panteón de París es un monumento de estilo neoclásico situado en el V distrito de París. Erigido en el corazón del Barrio Latino, en la montaña Santa Genoveva, está en el centro de la plaza del Panteón y rodeado por el Ayuntamiento del V distrito, el Henri-IV, la iglesia Saint Étienne du Mont, la biblioteca de Santa Genoveva, la Universidad de París I (Panthéon-Sorbonne) y la Universidad de París II (Panthéon-Assas). La calle Soufflot le dibuja una perspectiva hasta el jardín de Luxemburgo.","de":"Das Panthéon auf dem Hügel der heiligen Genoveva in Paris ist die nationale Ruhmeshalle Frankreichs und die Grabstätte berühmter französischer Persönlichkeiten."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Pante%C3%A3o_(Paris)","nl":"https://nl.wikipedia.org/wiki/Panth%C3%A9on_(Parijs)","pl":"https://pl.wikipedia.org/wiki/Panteon_w_Pary%C5%BCu","ja":"https://ja.wikipedia.org/wiki/%E3%83%91%E3%83%B3%E3%83%86%E3%82%AA%E3%83%B3_(%E3%83%91%E3%83%AA)","ru":"https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D0%BD%D1%82%D0%B5%D0%BE%D0%BD_(%D0%9F%D0%B0%D1%80%D0%B8%D0%B6)","ar":"https://ar.wikipedia.org/wiki/%D9%85%D9%82%D8%A8%D8%B1%D8%A9_%D8%A7%D9%84%D8%B9%D8%B8%D9%85%D8%A7%D8%A1_(%D8%A8%D8%A7%D8%B1%D9%8A%D8%B3)","zh-CN":"https://zh.wikipedia.org/wiki/%E5%85%88%E8%B4%A4%E7%A5%A0","ko":"https://ko.wikipedia.org/wiki/%ED%8C%A1%ED%85%8C%EC%98%B9","zh-TW":"https://zh.wikipedia.org/wiki/%E5%85%88%E8%B4%A4%E7%A5%A0","en":"https://en.wikipedia.org/wiki/Panth%C3%A9on","fr":"https://fr.wikipedia.org/wiki/Panth%C3%A9on_(Paris)","it":"https://it.wikipedia.org/wiki/Pantheon_(Parigi)","es":"https://es.wikipedia.org/wiki/Pante%C3%B3n_de_Par%C3%ADs","de":"https://de.wikipedia.org/wiki/Panth%C3%A9on_(Paris)"},"site":"http://www.paris-pantheon.fr/"},{"id":"wd-Q217925","cat":"parcs","ville":"paris","nom":{"fr":"Champ-de-Mars","en":"Champ de Mars","es":"Campo de Marte","de":"Champ de Mars","it":"Campo di Marte","pt":"Campo de Marte","nl":"Champ-de-Mars","pl":"Pole Marsowe","ru":"Марсово поле","uk":"Марсове поле","ar":"شون دو مارس","he":"שאן דה מארס","tr":"Champ de Mars","el":"Πεδίον του Άρεως","sv":"Champ de Mars","da":"Marsmarken","nb":"Marsmarken","fi":"Marskenttä","cs":"Champ-de-Mars","sk":"Marsove polia","hu":"Mars-mező","ro":"Champ de Mars","bg":"Марсово поле","hr":"Champ de Mars","sr":"Marsova polja","sl":"Marsove poljane","lt":"Marso laukas","et":"Marsi väljak (Pariis)","ca":"Camp de Mart","eu":"Marteren Zelaia","is":"Champs de Mars","mk":"Марсово Поле (Париз)","zh-CN":"战神广场","zh-TW":"戰神廣場","ja":"シャン・ド・マルス公園","ko":"마르스 광장","hi":"शाँ द मार्स","fa":"میدان شان دو مارس","th":"ช็องเดอมาร์ส","vi":"Champ-de-Mars","id":"Champ de Mars","ms":"Champ de Mars"},"lat":48.85613,"lon":2.29803,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/MG-Paris-Champ_de_Mars.jpg/960px-MG-Paris-Champ_de_Mars.jpg","page":"https://commons.wikimedia.org/wiki/File:MG-Paris-Champ_de_Mars.jpg","auteur":"Mattgirling","licence":"CC BY-SA 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q217925"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Champ-de-Mars_(Paris)"}],"recupere":"2026-11-14","court":{"fr":"espace vert de Paris (France)","en":"large public green space in Paris, France","es":"Espacio verde público en París","de":"Platz in Paris‎","it":"giardino pubblico di Parigi, Francia","pt":"parque público no 7º arrondissement de Paris, França","nl":"plein in 7e arrondissement van Parijs, Frankrijk","ru":"парк в 7-м округе Парижа","uk":"публічний парк в 7-му окрузі Парижа","ar":"مساحة خضراء عمومية كبيرة في الدائرة السابعة في باريس، فرنسا","he":"כיכר בפריז, צרפת","el":"δημόσιος κήπος στο Παρίσι","fi":"puisto Pariisissa","cs":"park v Paříži","hu":"nyilvános park Párizsban","bg":"парк в Париж, Франция","ja":"パリの公園","ko":"프랑스 파리에 위치한 공원"},"long":{"pt":"Campo de Marte é uma das maiores áreas verdes em Paris, França, localizada no sétimo distrito (arrondissement), entre a Torre Eiffel a noroeste e a Escola Militar a sudeste.","nl":"De Champ-de-Mars (Marsveld) is de naam van een uitgestrekt open parkgebied in het 7e arrondissement van de Franse hoofdstad Parijs. Het wordt in het noordwesten begrensd door de Eiffeltoren, en in het zuidoosten door de École Militaire.","pl":"Pole Marsowe – rozległy park, znajdujący się w Paryżu, między wieżą Eiffla na północnym zachodzie i École militaire na południowym wschodzie.","ru":"Ма́рсово поле — общественный парк в 7-м округе Парижа, между Эйфелевой башней с северо-запада и Военной школой с юго-востока. Находится в западной части города, на левом берегу Сены.","zh-CN":"战神广场 是一座位于法国巴黎第七区的广大带状公园，介于位在其西北方的埃菲尔铁塔，以及在其东南方的巴黎军校之间。2024年巴黎奥运会沙滩排球比赛在此举行。","zh-TW":"戰神廣場 是一座位於法國巴黎第七區的廣大帶狀公園，介於位在其西北方的艾菲爾鐵塔，以及在其東南方的巴黎軍校之間。2024年巴黎奧運會沙灘排球比賽在此舉行。","ar":"شون دو مارس أو شان دو مارس هي ساحة عامة خضراء، تقع بالحي السابع من مدينة باريس، في المساحة المحصورة بين برج إيفل والمدرسة العسكرية علي طول المحور الممتد جنوب-شرق / شمال-غرب. وتعتبر من أشهر الساحات في فرنسا؛ ليس فقط لما تعطيه من جمال بصري علي طول هذا المحور، ولكن أيضا نظرا لما شهدته من أحداث كثيرة منذ إنشاءها.","ja":"シャン・ド・マルス公園 は、フランス・パリの7区にある公園である。24.3haの面積を有するパリ有数の緑地であり、公園の北西側にはエッフェル塔、南東側にはエコール・ミリテール（陸軍士官学校）が隣接している。 1867年の第2回パリ万国博覧会を最初として1937年までに5回の国際博覧会が開催され、大きなパビリオンが林立した。1991年には、この公園を含むパリのセーヌ川周辺は「パリのセーヌ河岸」として世界遺産に登録された。","ko":"마르스 광장(프랑스어: Champ de Mars)은 프랑스 파리시에 있는 공원이다. 7구에 위치해 있으며 에펠탑의 북서쪽, 에콜 밀리테르(École Militaire)의 남동쪽에 있다. \"마르스 광장\"이라는 이름이 붙은 이유는 이곳이 군사 훈련 장소로 사용되었기 때문이다.","en":"The Champ de Mars is a large public greenspace in Paris, France, located in the seventh arrondissement, between the Eiffel Tower to the northwest and the École Militaire to the southeast. The park is named after the Campus Martius in Rome, which was dedicated to the god Mars. The name alludes to the fact that the lawns here were formerly used as drilling and marching grounds by the French military.","es":"El Campo de Marte es un vasto jardín público totalmente abierto situado en el séptimo distrito de París, entre la Torre Eiffel, al noroeste y la Escuela militar al sureste. Con sus 24,5 hectáreas, el jardín es uno de los espacios verdes más grandes de París. Rico de una historia bicentenaria, recibe a parisinos y turistas durante todo el año en una amplia gama de actividades.","de":"Das Champ de Mars, auch als Parc du Champ de Mars bezeichnet, ist eine ursprünglich zu militärischen, später mehrfach zu Ausstellungszwecken genutzte Großgrünfläche von heute 24,3 ha im 7. Arrondissement von Paris. An seinem nordwestlichen Ende erhebt sich unweit der Seine, als Relikt der Weltausstellung von 1889, der Eiffelturm, im Südosten wird es durch den Place Joffre und die Avenue de La Motte-Picquet von der École Militaire abgegrenzt.","fr":"Le Champ-de-Mars est un vaste jardin public entièrement ouvert, situé à Paris dans le quartier du Gros-Caillou du 7e arrondissement, entre la tour Eiffel au nord-ouest et l'École militaire au sud-est. D'une superficie de 24,3 ha, le jardin du Champ-de-Mars est l'un des plus grands espaces verts de Paris.","it":"Il Campo di Marte è un giardino pubblico di Parigi che si trova sulla rive gauche. È delimitato a nord-ovest dalla Torre Eiffel e a sud-est dall'École militaire."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Campo_de_Marte_(Paris)","nl":"https://nl.wikipedia.org/wiki/Champ-de-Mars","pl":"https://pl.wikipedia.org/wiki/Pole_Marsowe_(Pary%C5%BC)","ru":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B0%D1%80%D1%81%D0%BE%D0%B2%D0%BE_%D0%BF%D0%BE%D0%BB%D0%B5_(%D0%9F%D0%B0%D1%80%D0%B8%D0%B6)","zh-CN":"https://zh.wikipedia.org/wiki/%E6%88%B0%E7%A5%9E%E5%BB%A3%E5%A0%B4_(%E5%B7%B4%E9%BB%8E)","zh-TW":"https://zh.wikipedia.org/wiki/%E6%88%B0%E7%A5%9E%E5%BB%A3%E5%A0%B4_(%E5%B7%B4%E9%BB%8E)","ar":"https://ar.wikipedia.org/wiki/%D8%B4%D9%88%D9%86_%D8%AF%D9%88_%D9%85%D8%A7%D8%B1%D8%B3","ja":"https://ja.wikipedia.org/wiki/%E3%82%B7%E3%83%A3%E3%83%B3%E3%83%BB%E3%83%89%E3%83%BB%E3%83%9E%E3%83%AB%E3%82%B9%E5%85%AC%E5%9C%92","ko":"https://ko.wikipedia.org/wiki/%EB%A7%88%EB%A5%B4%EC%8A%A4_%EA%B4%91%EC%9E%A5_(%ED%8C%8C%EB%A6%AC)","en":"https://en.wikipedia.org/wiki/Champ_de_Mars","es":"https://es.wikipedia.org/wiki/Campo_de_Marte_(Par%C3%ADs)","de":"https://de.wikipedia.org/wiki/Champ_de_Mars","fr":"https://fr.wikipedia.org/wiki/Champ-de-Mars_(Paris)","it":"https://it.wikipedia.org/wiki/Campo_di_Marte_(Parigi)"}},{"id":"wd-Q329852","cat":"chateaux","ville":"paris","nom":{"fr":"Palais du Luxembourg","en":"Luxembourg Palace","es":"Palacio del Luxemburgo","de":"Palais du Luxembourg","it":"Palazzo del Lussemburgo","pt":"Palácio do Luxemburgo","nl":"Palais du Luxembourg","pl":"Pałac Luksemburski","ru":"Люксембургский дворец","uk":"Люксембурзький палац","ar":"قصر لوكسمبورغ","he":"ארמון לוקסמבורג","tr":"Lüksemburg Sarayı","el":"Παλάτι του Λουξεμβούργου","sv":"Palais du Luxembourg","da":"Palais du Luxembourg","nb":"Palais du Luxembourg","fi":"Palais du Luxembourg","cs":"Lucemburský palác","sk":"Luxemburský palác","hu":"Louxembourg-palota","bg":"Люксембургски дворец","sr":"Луксембуршка палата","sl":"Luksemburška palača","lv":"Luksemburgas pils","et":"Luxembourgi palee","ca":"Palau de Luxemburg","eu":"Luxenburgoko Jauregia","is":"Lúxemborgarhöll","zh-CN":"卢森堡宫","zh-TW":"盧森堡宮","ja":"リュクサンブール宮殿","ko":"뤽상부르궁","fa":"کاخ لوکزامبورگ","th":"พระราชวังลุกซ็องบูร์","vi":"Cung điện Luxembourg","id":"Palais du Luxembourg","ms":"Luxembourg Palace","ur":"لکسمبرگ محل"},"lat":48.848333,"lon":2.3375,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/2017_-_Le_palais_du_Luxembourg%2C_dans_le_jardin_du_Luxembourg%2C_Paris_-_3.jpg/960px-2017_-_Le_palais_du_Luxembourg%2C_dans_le_jardin_du_Luxembourg%2C_Paris_-_3.jpg","page":"https://commons.wikimedia.org/wiki/File:2017_-_Le_palais_du_Luxembourg,_dans_le_jardin_du_Luxembourg,_Paris_-_3.jpg","auteur":"Luis Miguel Bugallo Sánchez (Lmbuga)","licence":"CC BY-SA 4.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q329852"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Palais_du_Luxembourg"}],"recupere":"2026-11-14","court":{"fr":"palais dans le 6e arrondissement de Paris","en":"seat of the French Senate","es":"sede del Senado francés","de":"Schloss in Frankreich","it":"palazzo storico di Parigi, sede del Senato francese","nl":"paleis in Parijs, zetel van de Franse Senaat","pl":"siedziba izby wyższej Francji","ru":"дворец в Париже","ar":"قصر في فرنسا","sv":"palats i Paris 6:e arrondissement, beläget i den stora parken Jardin du Luxembourg","da":"palads i Paris' 6. arrondissement i parken Jardin du Luxembourg","fi":"Ranskan senaatin kokoontumispaikka Pariisissa","cs":"palác v Paříži","hu":"Párizsi épület","zh-TW":"盧森堡公園","ja":"フランス上院議事堂","ko":"프랑스 파리에 위치한 궁전","fa":"محل مجلس سنای فرانسه","vi":"trụ sở Thượng viện Pháp","id":"bangunan istana di Prancis"},"long":{"pt":"O Palácio do Luxemburgo é um palácio localizado no 6.º arrondissement de Paris, na França. Actualmente é a sede do Senado da França.","nl":"Het Palais du Luxembourg (Luxemburg-paleis) is een paleis in het 6e arrondissement van Parijs. Ten zuiden ervan ligt het stadspark Jardin du Luxembourg. In het paleis zetelt de Franse Senaat.","pl":"Pałac Luksemburski – pałac znajdujący się w Ogrodzie Luksemburskim w Paryżu, zaprojektowany przez Salomona de Brosse dla Marii Medycejskiej, małżonki Henryka IV. Jego budowa trwała od 1610 do 1630 roku. Na życzenie królowej projekt miał być wzorowany na pałacu Pittich we Florencji, gdzie spędziła dzieciństwo. Ostatecznie jednak powstał typowo francuski pałac z elementami włoskimi w kompozycji elewacji. Budowla ma trzy kondygnacje i wysoki, charakterystyczny dla epoki dach z lukarnami.","ru":"Люксембургский дворец — дворцово-парковый ансамбль в Париже, памятник архитектуры раннего классицизма, построенный для Марии Медичи по проекту Саломона Деброса в 1615—1631 годах в Люксембургском саду в, близ Латинского квартала, на месте Люксембургского отеля (особняка) покойного герцога Франсуа де Пине из рода Люксембургов.","ja":"リュクサンブール宮殿 は、フランスのパリにある宮殿。初期フレンチ・バロックの代表的建築物である。","ko":"뤽상부르궁(프랑스어: Palais du Luxembourg)은 프랑스 파리 6구에 위치한 궁전이다. 1615년부터 1645년까지 건축가 살로몬 드 보로세의 설계안을 따라 섭정이자 루이 13세의 어머니인 마리아 데 메디치를 위하여 지었다. 프랑스 혁명 이후에는 의회 건물로 개축되어 사용되었고, 1835년부터 1856년까지 또다시 대대적인 재건 작업을 거쳐 현재의 모습으로 이르게 되었다. 1958년부터는 프랑스 제5공화국의 상원 의사당으로 사용되었으며, 주위는 뤽상부르 공원으로 일반인들에게도 공개되고 있다.","zh-CN":"卢森堡宫，位于法国首都巴黎第六区卢森堡公园内，是法国参议院所在。该宫殿始建于1615年，当时是玛丽·德·美第奇的住所。","zh-TW":"盧森堡宮，位於法國首都巴黎第六區盧森堡公園內，是法國參議院所在。該宮殿始建於1615年，當時是瑪麗·德·美第奇的住所。","ar":"قصر لوكسمبورغ يقع في العاصمة الفرنسية باريس ويعود تاريخ بنائه لعام 1620 م وبني من أجل والدة الملك لويس الثالث عشر وهو المقر الرسمي لمجلس الشيوخ الفرنسي.","en":"The Luxembourg Palace is at 15 Rue de Vaugirard in the 6th arrondissement of Paris, France. It was originally built (1615–1645) to the designs of the French architect Salomon de Brosse to be the royal residence of the regent Marie de' Medici, mother of King Louis XIII. After the Revolution it was refashioned (1799–1805) by Jean-François Chalgrin into a legislative building and subsequently greatly enlarged and remodeled (1835–1856) by Alphonse de Gisors.","es":"El palacio del Luxemburgo es un palacio francés del siglo XVII y estilo barroco ubicado en el VI distrito de París. El palacio, actual sede del Senado francés, fue construido por el arquitecto Salomon de Brosse para María de Médici entre 1615 y 1627. Sufrió numerosas ampliaciones y recortes a lo largo de su historia, y el diseño actual corresponde en su mayor parte a las obras realizadas por el arquitecto Jean-François Chalgrin durante el Primer Imperio francés. Fue recortado con posterioridad por las obras de urbanización periféricas del barón Haussmann.","de":"Das Palais du Luxembourg ist ein Schloss im 6. Arrondissement von Paris, umgeben von einer ursprünglich barocken Parklandschaft aus dem frühen 17. Jahrhundert, genannt Jardin du Luxembourg. Es diente zunächst Mitgliedern der königlichen Familie als Wohnsitz, wurde während der Revolution in Staatsbesitz überführt und ist seit 1800 Sitz des Senats, der zweiten parlamentarischen Kammer Frankreichs.","fr":"Le palais du Luxembourg, situé dans le 6e arrondissement de Paris dans le nord du jardin du Luxembourg, est le siège du Sénat français, qui fut installé en 1799 dans le palais construit au début du XVIIe siècle par Marie de Médicis, alors veuve d'Henri IV, roi de France et de Navarre. Il appartient au domaine de cette assemblée, qui comprend également, à proximité du palais, l'hôtel du Petit Luxembourg, résidence du président du Sénat, le musée du Luxembourg, et l'ensemble du jardin.","it":"Il palazzo del Lussemburgo è un edificio storico-monumentale di Parigi. Nato come residenza della regina Maria de' Medici, dal 1958 è sede del Senato francese. Dal 1862 il palazzo è classificato Monumento storico di Francia."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Pal%C3%A1cio_do_Luxemburgo","nl":"https://nl.wikipedia.org/wiki/Palais_du_Luxembourg","pl":"https://pl.wikipedia.org/wiki/Pa%C5%82ac_Luksemburski","ru":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D0%BA%D1%81%D0%B5%D0%BC%D0%B1%D1%83%D1%80%D0%B3%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86","ja":"https://ja.wikipedia.org/wiki/%E3%83%AA%E3%83%A5%E3%82%AF%E3%82%B5%E3%83%B3%E3%83%96%E3%83%BC%E3%83%AB%E5%AE%AE%E6%AE%BF","ko":"https://ko.wikipedia.org/wiki/%EB%A4%BD%EC%83%81%EB%B6%80%EB%A5%B4%EA%B6%81","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%A3%AE%E5%A0%A1%E5%AE%AB","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%A3%AE%E5%A0%A1%E5%AE%AB","ar":"https://ar.wikipedia.org/wiki/%D9%82%D8%B5%D8%B1_%D9%84%D9%88%D9%83%D8%B3%D9%85%D8%A8%D9%88%D8%B1%D8%BA","en":"https://en.wikipedia.org/wiki/Luxembourg_Palace","es":"https://es.wikipedia.org/wiki/Palacio_del_Luxemburgo","de":"https://de.wikipedia.org/wiki/Palais_du_Luxembourg","fr":"https://fr.wikipedia.org/wiki/Palais_du_Luxembourg","it":"https://it.wikipedia.org/wiki/Palazzo_del_Lussemburgo"},"site":"https://www.senat.fr/lng/welcome-to-french-senate/the-luxembourg-palace.html","adresse":"15 Rue de Vaugirard"},{"id":"wd-Q309458","cat":"parcs","ville":"paris","nom":{"fr":"Jardin du Luxembourg","en":"Jardin du Luxembourg","es":"Jardín del Luxemburgo","de":"Jardin du Luxembourg","it":"Giardini del Lussemburgo","pt":"Jardim de Luxemburgo","nl":"Jardin du Luxembourg","pl":"Ogród Luksemburski","ru":"Люксембургский сад","uk":"Люксембурзький сад","ar":"حديقة لوكسمبورغ","he":"גני לוקסמבורג","tr":"Lüksemburg Bahçesi","el":"Κήπος του Λουξεμβούργου","sv":"Jardin du Luxembourg","da":"Jardin du Luxembourg","nb":"Luxembourghagen","fi":"Luxembourgin puisto","cs":"Jardin du Luxembourg","sk":"Luxemburské záhrady","hu":"Luxembourg-kert","ro":"Grădina Luxemburg","bg":"Люксембургска градина","sr":"Парк Луксембург","sl":"Jardin du Luxembourg","et":"Luxembourgi aed","ca":"Jardin du Luxembourg","eu":"Luxenburgoko lorategiak","is":"Lúxemborgargarðurinn","zh-CN":"卢森堡公园","zh-TW":"盧森堡公園","ja":"リュクサンブール公園","ko":"뤽상부르 공원","hi":"लक्ज़मबर्ग उद्यान","bn":"জারদাঁ দু লুক্সমবুর","fa":"پارک لوکزامبورگ","th":"สวนลุกซ็องบูร์","vi":"Vườn Luxembourg","id":"Jardin du Luxembourg","ms":"Jardin du Luxembourg"},"lat":48.846944,"lon":2.337222,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/LuxembourgMontparnasse_2.jpg/960px-LuxembourgMontparnasse_2.jpg","page":"https://commons.wikimedia.org/wiki/File:LuxembourgMontparnasse_2.jpg","auteur":"Kirua","licence":"Public domain"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q309458"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Jardin_du_Luxembourg"}],"recupere":"2026-11-14","court":{"fr":"parc situé à Paris","en":"urban park in Paris, France","es":"parque urbano en París, Francia","de":"Garten in Paris","it":"giardino pubblico di Parigi","nl":"stadspark in het 6e arrondissement van Parijs, Frankrijk","pl":"park miejski we Francji","ar":"حديقة حضرية في باريس، فرنسا","he":"פארק עירוני בפריז","da":"park i Paris, Frankrig","fi":"puisto Pariisissa","cs":"park v Paříži","hu":"park Párizsban (Franciaország)","sl":"mestni park v Parizu (Francija)","zh-TW":"公園","ja":"パリの公園"},"long":{"nl":"De Jardin du Luxembourg is een stadspark in het 6e arrondissement van Parijs. Het werd in 1612 op verzoek van Maria de' Medici aangelegd als park rond het Palais du Luxembourg. Tijdens het Premier Empire restaureerde Jean-François-Thérèse Chalgrin het park. Sindsdien is het eigendom van de Franse Senaat. Parijzenaars spreken van le Luco of le jardin des sénateurs.","pl":"Ogród Luksemburski – park miejski w Paryżu, we Francji o powierzchni 224 500 m².","ru":"Люксембу́ргский сад — дворцово-парковый ансамбль в центре Парижа, известная достопримечательность города. Бывший королевский, а ныне государственный дворцовый парк в парижском Латинском квартале занимает площадь в 26 гектаров. В парке расположен Люксембургский дворец, в котором заседает Сенат, вторая палата французского парламента.","ja":"リュクサンブール公園 は、フランスのパリ6区にある公園。リュクサンブール庭園と訳されることもある。","zh-CN":"卢森堡公园 是一座处于巴黎第六区，拉丁区中央的公园，于1612年玛丽·德·美第奇的统治下建成。卢森堡公园面积为224,500平方米，如今是巴黎学生、游客聚集之地。","pt":"O Jardim do Luxemburgo em francês: Jardin du Luxembourg é um grande parque público da cidade de Paris com mais de 22,4 hectares, localizado no 6.º arrondissement. O Jardim do Luxemburgo atualmente pertence ao Senado da França, que está sediado no famoso Palácio do Luxemburgo.","ar":"حديقة لوكسمبوغ هي ثاني أكبر حديقة عامة في باريس. ظهرت الحديقة في رواية فكتور هوغو المشهورة باسم البؤساء.","zh-TW":"盧森堡公園 是一座處於巴黎第六區，拉丁區中央的公園，於1612年瑪麗·德·美第奇的統治下建成。盧森堡公園面積為224,500平方公尺，如今是巴黎學生、遊客聚集之地。","ko":"뤽상부르 공원(프랑스어: Jardin du Luxembourg)은 프랑스 파리 6구에 위치한 공원이자 정원이다.","es":"El Jardín de Luxemburgo, apodado familiarmente Luco, es un conjunto de jardines que constituyen un gran parque público parisino de 22,45 ha, situado en el VI Distrito. El Jardín de Luxemburgo es también el jardín del Senado francés, cuya sede parlamentaria se encuentra en el palacio de Luxemburgo.","de":"Der Jardin du Luxembourg ist ein früher königlicher, heute staatlicher Schlosspark im Pariser Quartier Latin (6. Arrondissement) mit einer Fläche von 26 Hektar. Die Anlage gehört zum Palais du Luxembourg, in dem der Senat tagt, das Oberhaus des französischen Parlamentes.","fr":"Le jardin du Luxembourg est un jardin ouvert au public, situé dans le 6e arrondissement de Paris. Créé en 1612 à la demande de Marie de Médicis pour accompagner le palais du Luxembourg, il a fait l'objet d'une restauration dirigée par l'architecte Jean-François Chalgrin sous le Premier Empire et appartient désormais au domaine du Sénat. Il s'étend sur 23 hectares agrémentés de parterres de fleurs et de sculptures.","en":"The Jardin du Luxembourg, known in English as the Luxembourg Garden, colloquially referred to as the Jardin du Sénat, is located in the 6th arrondissement of Paris, France.","it":"I giardini del Lussemburgo sono i giardini alla francese pubblici del Palazzo del Lussemburgo, a Parigi."},"wiki":{"nl":"https://nl.wikipedia.org/wiki/Jardin_du_Luxembourg","pl":"https://pl.wikipedia.org/wiki/Ogr%C3%B3d_Luksemburski","ru":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D0%BA%D1%81%D0%B5%D0%BC%D0%B1%D1%83%D1%80%D0%B3%D1%81%D0%BA%D0%B8%D0%B9_%D1%81%D0%B0%D0%B4","ja":"https://ja.wikipedia.org/wiki/%E3%83%AA%E3%83%A5%E3%82%AF%E3%82%B5%E3%83%B3%E3%83%96%E3%83%BC%E3%83%AB%E5%85%AC%E5%9C%92","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%A3%AE%E5%A0%A1%E5%85%AC%E5%9B%AD","pt":"https://pt.wikipedia.org/wiki/Jardim_de_Luxemburgo","ar":"https://ar.wikipedia.org/wiki/%D8%AD%D8%AF%D9%8A%D9%82%D8%A9_%D9%84%D9%88%D9%83%D8%B3%D9%85%D8%A8%D9%88%D8%B1%D8%BA","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8D%A2%E6%A3%AE%E5%A0%A1%E5%85%AC%E5%9B%AD","ko":"https://ko.wikipedia.org/wiki/%EB%A4%BD%EC%83%81%EB%B6%80%EB%A5%B4_%EA%B3%B5%EC%9B%90","es":"https://es.wikipedia.org/wiki/Jardines_de_Luxemburgo","de":"https://de.wikipedia.org/wiki/Jardin_du_Luxembourg","fr":"https://fr.wikipedia.org/wiki/Jardin_du_Luxembourg","en":"https://en.wikipedia.org/wiki/Jardin_du_Luxembourg","it":"https://it.wikipedia.org/wiki/Giardini_del_Lussemburgo"},"site":"https://jardin.senat.fr"},{"id":"wd-Q329948","cat":"chateaux","ville":"paris","nom":{"fr":"Palais-Royal","en":"Palais-Royal","es":"Palacio Real","de":"Palais-Royal","it":"Palais-Royal","pt":"Palais Royal","nl":"Palais-Royal","pl":"Palais-Royal","ru":"Пале-Рояль","uk":"Пале-Рояль","ar":"القصر الملكي","he":"פאלה רויאל","tr":"Palais-Royal","el":"Παλαί Ρουαγιάλ","sv":"Palais-Royal","da":"Palais-Royal","nb":"Palais Royal","fi":"Palais-Royal","cs":"Palais Royal","sk":"Palais Royal","hu":"Palais-Royal","ro":"Palais-Royal","hr":"Palais Royal","sr":"Краљевска палата (Париз)","sl":"Palais-Royal","lt":"Karališkieji rūmai (Paryžius)","et":"Palais-Royal","ca":"Palau Reial","eu":"Parisko Errege Jauregia","zh-CN":"巴黎皇家宫殿","zh-TW":"巴黎皇家宮殿","ja":"パレ・ロワイヤル","ko":"팔레 루아얄","fa":"پله رویال","th":"ปาแล-รัวยาล","vi":"Palais-Royal","id":"Palais-Royal","ms":"Palais-Royal","ur":"رویال محل"},"lat":48.863333,"lon":2.336944,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Conseil_d%27Etat_Paris_WA.jpg/960px-Conseil_d%27Etat_Paris_WA.jpg","page":"https://commons.wikimedia.org/wiki/File:Conseil_d%27Etat_Paris_WA.jpg","auteur":"Marie-Lan Nguyen","licence":"Public domain"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q329948"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Palais-Royal"}],"recupere":"2026-11-14","court":{"fr":"palais dans le 1er arrondissement de Paris","en":"palace and an associated garden located in the 1st arrondissement of Paris","es":"palacio en el distrito 1 de París","de":"Palais in Paris, Frankreich","it":"edificio storico di Parigi, Francia","nl":"paleis in Parijs, zetel van de Conseil d'État","pl":"Zespół pałacowy w Paryżu","ru":"площадь, дворец и парк, расположенные в Париже напротив северного крыла Лувра","ar":"قصر في فرنسا","he":"ארמון בפריז שבמאה ה-17 שימש כבית תיאטרון","sv":"palats i 1:a arrondissementet i Paris, Frankrike","nb":"slott i Paris","fi":"palatsi Ranskassa","cs":"palác v Paříži","hu":"palota Párizsban","ro":"palat și o grădină asociată situate în arondismentul 1 al Parisului","sl":"palača in vrt v 1. okrožju Pariza","ca":"Conjunt monumental parisí","zh-CN":"巴黎建筑","ja":"パリの建築物","th":"พระราชวังและสวน ตั้งอยู่ในเขต 1 ของกรุงปารีส","id":"salah satu teater di Prancis"},"long":{"ru":"Пале́-Роя́ль, Пале-Руайаль — площадь, дворец и парк, расположенные в Париже напротив северного крыла Лувра.","pt":"O Palais Royal é um palácio e jardim localizado no 1.º arrondissement de Paris, na França. Em frente à ala norte do Louvre, o seu famoso pátio delimitado por colunas se localiza em frente à Place du Palais-Royal, a qual foi bastante ampliada pelo Barão Haussmann, depois da abertura da Rue de Rivoli por Napoleão.","pl":"Palais-Royal – pałac położony w centrum Paryża, 150 m na północ od Luwru, siedziba francuskiej Rady Stanu, Rady Konstytucyjnej i Ministerstwa Kultury, połączony z francuskim Teatrem Narodowym Comédie-Française.","ar":"القصر الملكي أو قصر الكاردينال، هو قصر يقع في المنطقة الأولى لباريس. كان القصر مقر الإقامة الشخصية للكاردينال ريشيليو. بدأ المهندس المعماري جاك لوميير تصميمه في عام 1629؛ وبدأ بالبناء في عام 1633 وأنتهى منه في عام 1639. بعد وفاة ريشيليو في عام 1642 أصبح القصر ملكا للملك وأكتسب الاسم الجديد القصر الملكي.","ja":"パレ・ロワイヤル は、パリの1区にある歴史的建造物。","zh-CN":"皇家宫殿 是位于法国首都巴黎第一区的宫殿建筑，与卢浮宫的北翼遥遥相对，曾是奥尔良王朝家族的府邸。1830年七月革命后，奥尔良公爵路易-腓力三世登基成为路易-腓力一世，这座宫殿依然是这位新君主的主要居所。它的著名前院与巴黎皇家宫殿广场之间由达尼埃尔·比朗设计的石柱所相隔。自拿破仑时期建设的里沃利路，这个广场被乔治-欧仁·奥斯曼扩建为今天的模样。","nl":"Het Palais-Royal is een paleis in het centrum van Parijs, vlak naast het Louvre. Het is een heel gebouwencomplex in classicistische stijl en omvat een theater en een tuin omringd door zuilengalerijen.","zh-TW":"皇家宮殿 是位於法國首都巴黎第一區的宮殿建築，與羅浮宮的北翼遙遙相對，曾是奧爾良王朝家族的府邸。1830年七月革命後，奧爾良公爵路易-腓力三世登基成為路易-腓力一世，這座宮殿依然是這位新君主的主要居所。它的著名前院與巴黎皇家宮殿廣場之間由達尼埃爾·比朗設計的石柱所相隔。自拿破崙時期建設的里沃利路，這個廣場被喬治-歐仁·奧斯曼擴建為今天的模樣。","ko":"팔레 루아얄(Palais Royal)은 프랑스 파리의 역사적 건물로, 현재는 회랑으로 둘러싸인 정원과 현대 미술을 감상할 수 있는 장소이다.","en":"The Palais-Royal is a former French royal palace located on Rue Saint-Honoré in the 1st arrondissement of Paris. The screened entrance court faces the Place du Palais-Royal, opposite the Louvre. Originally called the Palais-Cardinal, it was built for Cardinal Richelieu from about 1633 to 1639 by architect Jacques Lemercier. Richelieu bequeathed it to Louis XIII, before Louis XIV gave it to his younger brother, Philippe I, Duke of Orléans. As the succeeding Dukes of Orléans made such extensive alterations over the years, almost nothing remains of Lemercier's original design.","it":"Il Palais-Royal, insieme monumentale a nord del palazzo del Louvre nel I arrondissement di Parigi, è un luogo importante della storia della Francia e della vita parigina. Fino al 1848 appartenne alla dinastia d'Orléans.","fr":"Le Palais-Royal, ensemble monumental au nord du palais du Louvre dans le 1er arrondissement de Paris, est un haut lieu de l’histoire de France et de la vie parisienne.","de":"Das Palais Royal, früher Palais Cardinal, ist ein Pariser Stadtpalast im 1. Arrondissement, etwa 150 Meter nördlich des Louvre. Das Palais beherbergt heute in seinem Haupttrakt den Staatsrat, im Westflügel die Comédie-Française und den Verfassungsrat und im Ostflügel das Kulturministerium.","es":"El Palais-Royal es un conjunto monumental parisino —un palacio, unos jardines, unas galerías y un teatro— situado al norte del palacio del Louvre, en el I distrito de París, que fue y es un destacado lugar de la historia de Francia y de la vida parisina."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B5-%D0%A0%D0%BE%D1%8F%D0%BB%D1%8C","pt":"https://pt.wikipedia.org/wiki/Palais_Royal","pl":"https://pl.wikipedia.org/wiki/Palais-Royal","ar":"https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%82%D8%B5%D8%B1_%D8%A7%D9%84%D9%85%D9%84%D9%83%D9%8A","ja":"https://ja.wikipedia.org/wiki/%E3%83%91%E3%83%AC%E3%83%BB%E3%83%AD%E3%83%AF%E3%82%A4%E3%83%A4%E3%83%AB","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E7%9A%87%E5%AE%B6%E5%AE%AE%E6%AE%BF","nl":"https://nl.wikipedia.org/wiki/Palais-Royal","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E9%BB%8E%E7%9A%87%E5%AE%B6%E5%AE%AE%E6%AE%BF","ko":"https://ko.wikipedia.org/wiki/%ED%8C%94%EB%A0%88_%EB%A3%A8%EC%95%84%EC%96%84","en":"https://en.wikipedia.org/wiki/Palais-Royal","it":"https://it.wikipedia.org/wiki/Palais-Royal","fr":"https://fr.wikipedia.org/wiki/Palais-Royal","de":"https://de.wikipedia.org/wiki/Palais_Royal","es":"https://es.wikipedia.org/wiki/Palais-Royal"},"site":"https://www.domaine-palais-royal.fr"},{"id":"wd-Q810700","cat":"culture","ville":"paris","nom":{"fr":"Bataclan","en":"Bataclan","es":"Bataclan","de":"Bataclan","it":"Bataclan","pt":"Bataclan","nl":"Bataclan","pl":"Bataclan","ru":"Батаклан","uk":"Батаклан","ar":"باتاكلان","he":"תיאטרון בטאקלאן","el":"Θέατρο Μπατακλάν","sv":"Bataclan","da":"Bataclan","nb":"Bataclan","fi":"Bataclan","cs":"Bataclan","sk":"Bataclan","hu":"Bataclan","ro":"Bataclan","sl":"Bataclan","lt":"Bataclan","ca":"Bataclan","eu":"Bataclan","is":"Bataclan","mk":"Батаклан","zh-CN":"巴塔克蘭劇院","ja":"バタクラン","ko":"바타클랑","fa":"تئاتر باتاکلان","vi":"Bataclan","ms":"Bataclan"},"lat":48.863056,"lon":2.370833,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Bataclan_-_Paris_%283448973995%29.jpg/960px-Bataclan_-_Paris_%283448973995%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Bataclan_-_Paris_(3448973995).jpg","auteur":"Céline Harrand from Dublin, Ireland","licence":"Public domain"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q810700"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Bataclan"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/1292143874"}],"recupere":"2026-11-14","court":{"fr":"salle des arts du spectacle dans le 11ᵉ arrondissement de Paris","en":"theatre in Paris, France","es":"sala de espectáculos en París, Francia","de":"denkmalgeschütztes Gebäude mit Theater- und Konzertsaal im 11. Arrondissement von Paris","it":"teatro a Parigi","nl":"accommodatie voor uitvoerende kunst in 11e arrondissement van Parijs, Frankrijk","pl":"sala koncertowo-teatralna, kawiarnia w Paryżu","ru":"театр в Париже","ar":"مسرح في الدائرة الحادية عشرة في باريس، فرنسا","he":"תאטרון בפריז","sv":"teater i Paris, Frankrike","da":"spillested i Paris","cs":"koncertní sál v Paříži","sk":"koncertná sála v Paríži","sl":"gledališka in koncertna stavba v 11. pariškem okrožju","lt":"teatras, kuriame vyko vienas iš 2015 m. lapkričio 13 d. Paryžiaus teroristinių išpuolių","mk":"театар во Париз","ko":"등재된 사적"},"long":{"pt":"O Bataclan é uma sala de espetáculos localizada no 11.º arrondissement de Paris, na França. Foi construído em 1864 pelo arquiteto Charles Duval. O seu nome refere-se a \"Ba-Ta-Clan\", uma opereta de Jacques Offenbach.","nl":"De Bataclan is een theater aan de Boulevard Voltaire in het 11e arrondissement van de Franse hoofdstad Parijs. De naam verwijst naar de gelijknamige operette van Jacques Offenbach.","pl":"Bataclan – sala koncertowo-teatralna i kawiarnia położona przy 50 Boulevard Voltaire w 11. dzielnicy w Paryżu we Francji, otwarta 3 lutego 1865. Mieści ona na widowni do 1500 osób. Od 11 marca 1991 posiada status monument historique.","ru":"«Батакла́н» — театр в Париже, расположенный на бульваре Вольтера, 50 в XI округе.","ja":"バタクラン とは、1864年に建築家シャルル・デュバルによってフランス、パリ市11区ヴォルテール大通り50に建てられた劇場である。名称はジャック・オッフェンバックのオペレッタ（シノワズリミュージカル）のバタクランに由来する。","ar":"مسرح باتاكلان هو مسرح يقع في 50 بولفار فولتير في الدائرة 11 في باريس، فرنسا.","ko":"바타클랑(프랑스어: Bataclan)은 프랑스 파리 11구 볼테르 대로에 위치한 극장이다. 1864년 건축가 샤를 듀발이 건축했으며, 자크 오펜바흐의 동명의 오페라의 이름을 따왔다.","zh-CN":"巴塔克兰剧院 是法国巴黎第11区伏尔泰大道上的一座剧院，修建于1864年。巴塔克兰剧院的建筑带有中国风格，修建之初是座咖啡厅。2015年11月13日剧院发生大规模恐怖袭击，导致89人遇难。","zh-TW":"巴塔克蘭劇院 是法國巴黎第11區伏爾泰大道上的一座劇院，修建於1864年。巴塔克蘭劇院的建築帶有中國風格，修建之初是座咖啡廳。2015年11月13日劇院發生大規模恐怖襲擊，導致89人遇難。","en":"The Bataclan is a theatre located at 50 Boulevard Voltaire in the 11th arrondissement of Paris, France. Designed in 1864 by the architect Charles Duval, its name refers to Ba-ta-clan, an operetta by Jacques Offenbach. Since the early 1970s, it has been a venue for rock music. On 13 November 2015, 90 people were killed in a coordinated terrorist attack in the theatre.","it":"Il Bataclan, è una \"sala da spettacolo\" di Parigi, situata nell'XI arrondissement. Costruito nel 1864 su progetto dell'architetto Charles Duval, trae il suo nome dall'operetta in un atto di ambientazione cinese Ba-ta-clan di Jacques Offenbach, rappresentata nel 1855.","fr":"Le Bataclan, qui s'appelait à l'origine Le Grand Café Chinois-Théâtre Ba-ta-clan, est une salle de spectacle parisienne édifiée par l'architecte Charles Duval en 1864 et située au 50, boulevard Voltaire dans le 11e arrondissement.","es":"El Bataclan es una sala de espectáculos de París, situada en el bulevar Voltaire, en el XI Distrito. Diseñado en 1864 por el arquitecto Charles Duval, durante años se dedicó a la representación de vodeviles, revistas y conciertos. Desde principios de los años setenta del siglo XX, se convirtió en un escenario legendario para la música rock. El 11 de marzo de 1991 recibió la catalogación de monumento histórico de Francia.","de":"Das Bataclan [bataklɑ̃] ist ein Pariser Vergnügungsetablissement und Konzertsaal im 11. Arrondissement am Boulevard Voltaire 50 mit ehemals auffällig orientalisierender Architektur. Es wurde von 1864 bis 1865 nach Plänen des Architekten Charles Duval errichtet. Sein Name verweist auf die gleichnamige Operette von Jacques Offenbach (Ba-ta-clan)."},"wiki":{"pt":"https://pt.wikipedia.org/wiki/Bataclan","nl":"https://nl.wikipedia.org/wiki/Bataclan","pl":"https://pl.wikipedia.org/wiki/Bataclan","ru":"https://ru.wikipedia.org/wiki/%D0%91%D0%B0%D1%82%D0%B0%D0%BA%D0%BB%D0%B0%D0%BD","ja":"https://ja.wikipedia.org/wiki/%E3%83%90%E3%82%BF%E3%82%AF%E3%83%A9%E3%83%B3_(%E5%8A%87%E5%A0%B4)","ar":"https://ar.wikipedia.org/wiki/%D8%A8%D8%A7%D8%AA%D8%A7%D9%83%D9%84%D8%A7%D9%86","ko":"https://ko.wikipedia.org/wiki/%EB%B0%94%ED%83%80%ED%81%B4%EB%9E%91_(%EA%B7%B9%EC%9E%A5)","zh-CN":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E5%A1%94%E5%85%8B%E8%98%AD%E5%8A%87%E9%99%A2","zh-TW":"https://zh.wikipedia.org/wiki/%E5%B7%B4%E5%A1%94%E5%85%8B%E8%98%AD%E5%8A%87%E9%99%A2","en":"https://en.wikipedia.org/wiki/Bataclan_(theatre)","it":"https://it.wikipedia.org/wiki/Bataclan","fr":"https://fr.wikipedia.org/wiki/Bataclan","es":"https://es.wikipedia.org/wiki/Bataclan","de":"https://de.wikipedia.org/wiki/Bataclan"},"site":"https://www.bataclan.fr/","fauteuil":"no"},{"id":"osm-n678802941","cat":"restaurants","ville":"paris","nom":"Au Chien qui Fume","lat":48.861354,"lon":2.344844,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/678802941"}],"recupere":"2026-11-14","site":"https://www.auchienquifume.com/","adresse":"33 Rue du Pont Neuf, 75001 Paris","tel":"+33 1 42 36 07 42","horaires":"Mo-Su 08:00-01:00","fauteuil":"limited","cuisine":"french"},{"id":"osm-n681283199","cat":"restaurants","ville":"paris","nom":"Le Petit Bouillon Pharamond","lat":48.863006,"lon":2.348511,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/681283199"}],"recupere":"2026-11-14","site":"https://www.petitbouillonpharamond.com/","adresse":"24 Rue de la Grande Truanderie, 75001 Paris","tel":"+33 1 40 28 45 18","horaires":"Mo-Su 12:00-24:00","fauteuil":"limited","cuisine":"french"},{"id":"osm-n681294130","cat":"restaurants","ville":"paris","nom":"L'Escargot Montorgueil","lat":48.864168,"lon":2.346704,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/681294130"}],"recupere":"2026-11-14","site":"https://www.escargotmontorgueil.com/","adresse":"38 Rue Montorgueil, 75001 Paris","tel":"+33 1 42 36 83 51","horaires":"Mo-Su 09:00-02:00","fauteuil":"yes","cuisine":"french"},{"id":"osm-n247455918","cat":"cafes","ville":"paris","nom":"Le Café Marly","lat":48.861643,"lon":2.33593,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/247455918"}],"recupere":"2026-11-14","site":"https://cafe-marly.com/","adresse":"93 Rue de Rivoli, 75001 Paris","tel":"+33149260660","horaires":"Mo-Su 08:00-02:00","fauteuil":"yes"},{"id":"osm-n1425008424","cat":"marches","ville":"paris","nom":"Marché Alibert","lat":48.871969,"lon":2.368745,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/1425008424"}],"recupere":"2026-11-14","site":"https://www.paris.fr/equipements/marche-alibert-5472","horaires":"Su 07:00-15:00","fauteuil":"yes"},{"id":"osm-n1699170789","cat":"shopping","ville":"paris","nom":"A la Mère de Famille","lat":48.873953,"lon":2.342326,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/1699170789"}],"recupere":"2026-11-14","site":"https://www.lameredefamille.com/","adresse":"33 - 35 Rue du Faubourg Montmartre, 75009","tel":"+33147708369","horaires":"Mo-Sa 09:30-20:00; Su 10:00-19:30"},{"id":"dt-ef40ed10-e418-39eb-bf25-4712eec9a764","cat":"hotels","ville":"paris","nom":"SO/ Paris","lat":48.850006,"lon":2.362457,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/ef40ed10-e418-39eb-bf25-4712eec9a764"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé entre Notre-Dame, Bastille et le Marais, le nouveau flagship de SO/Paris sur les quais du 4e arrondissement de la Seine promet une expérience unique. Avec 162 chambres et suites, un restaurant, bar et club gérés par Paris Society, un Spa Maison CODAGE et une salle de fitness avec piscine, chaque détail est pensé pour satisfaire les visiteurs. Offrant des vues spectaculaires, SO/Paris invite à la découverte et à la détente. Parfait pour les amateurs de luxe et d'art de vivre."},"site":"https://soparis.com/","adresse":"10 rue Agrippa d'Aubigné, 75004 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","5 étoiles","Tourisme & Handicap mental"],"majSource":"2026-09-01"},{"id":"dt-7ff73c06-8c8b-376d-a691-15dc94ddf0ab","cat":"hotels","ville":"paris","nom":"Hôtel Trianon Rive Gauche","lat":48.847469,"lon":2.339989,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/7ff73c06-8c8b-376d-a691-15dc94ddf0ab"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé à Saint Germain des Prés, le Trianon Rive Gauche est un charmant hôtel 4 étoiles à Paris. Proche des incontournables de la capitale : Jardin du Luxembourg, Cathédrale Notre-Dame, Louvre, Musée d'Orsay. Derrière sa façade haussmannienne, ses 110 chambres offrent calme et confort. Lobby accueillant, salon élégant pour se détendre. Petit-déjeuner buffet convivial. Quartier Latin en face pour dîners. Équipe multi-lingue pour service personnalisé."},"site":"https://www.hoteltrianonrivegauche.com/","adresse":"1B rue de Vaugirard, 75006 Paris","labels":["4 étoiles","Clef Verte","Ecolabel européen"],"majSource":"2026-09-01"},{"id":"dt-314c75fd-9af7-3f92-8832-758f03f98ceb","cat":"hotels","ville":"paris","nom":"Le Grand Hôtel Cayré","lat":48.855285,"lon":2.325527,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/314c75fd-9af7-3f92-8832-758f03f98ceb"}],"recupere":"2026-11-14","long":{"fr":"Le K+K Hotel Cayré est un hôtel haut de gamme, installé dans le quartier de la Rue du Bac. Il se distingue par sa remarquable façade haussmannienne. Les chambres sont raffinées, et leur décoration sobre. Les suites sont pourvues d'un balcon et d'un salon. Les salles de bains sont faites de granit et de porcelaine. L'hôtel possède une salle de fitness, un sauna et une salle de réunion. Le bar lounge dispose d'une terrrase donnant sur le boulevard Raspail."},"site":"https://www.miirohotels.com/legrandhotelcayre","adresse":"4 boulevard Raspail, 75007 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","4 étoiles","Tourisme & Handicap mental"],"majSource":"2026-09-01"},{"id":"dt-aef1d450-7792-37ad-9529-ea4878c57a65","cat":"hotels","ville":"paris","nom":"Sofitel Le Scribe Paris Opéra","lat":48.870567,"lon":2.329731,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/aef1d450-7792-37ad-9529-ea4878c57a65"}],"recupere":"2026-11-14","long":{"fr":"L'Hôtel Scribe, ouvert en 1863, est un lieu emblématique de Paris. Ancien siège du Jockey Club, il a accueilli les premières projections cinématographiques des Frères Lumière en 1895 et des personnalités comme Joséphine Baker. La décoration par Wilson Associates mélange l'élégance parisienne à l'esprit Men's Club. L'ambiance haussmannienne du hall se reflète dans les chambres et Suites, le restaurant propose une cuisine raffinée et un brunch le dimanche."},"site":"http://www.hotel-scribe.com/","adresse":"1 rue Scribe, 75009 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","Clef Verte","5 étoiles"],"majSource":"2026-09-01"},{"id":"dt-bc6e3e50-3f92-35ce-9547-ce4af1bf4b9a","cat":"hotels","ville":"paris","nom":"Novotel Paris Les Halles","lat":48.860767,"lon":2.346532,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/bc6e3e50-3f92-35ce-9547-ce4af1bf4b9a"}],"recupere":"2026-11-14","long":{"fr":"Situé près du musée du Louvre, du Centre Georges Pompidou et du quartier du Marais, l'hôtel 4 étoiles Novotel Paris Les Halles allie design, technologie et confort. Avec ses 285 chambres, son restaurant panoramique, son bar et son bureau d'informations touristiques, il convient parfaitement aux séjours en famille ou aux voyages d'affaires. Ses 10 salles de réunion high-tech sont idéales pour les professionnels. Emplacement privilégié et services de qualité pour un séjour réussi à Paris."},"site":"http://www.novotelparisleshalles.com/","adresse":"8 place Marguerite de Navarre, 75001 Paris","labels":["4 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-dad89544-b24d-3533-97b5-af98a3062c8b","cat":"hotels","ville":"paris","nom":"Sofitel Paris Le Faubourg","lat":48.868412,"lon":2.321348,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/dad89544-b24d-3533-97b5-af98a3062c8b"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé, cet hôtel parisien vous transporte au cœur de la capitale, à proximité des Champs-Elysées, de la place de la Concorde, du Faubourg Saint-Honoré et des musées du Louvre et d'Orsay. Installé dans un bâtiment historique, il incarne l'élégance parisienne avec une touche de Haute Couture. Découvrez son bar tendance, son restaurant Blossom, ses terrasses ensoleillées et son charmant jardin secret, pour un séjour enchanteur à Paris."},"site":"http://www.sofitel-paris-lefaubourg.com/","adresse":"15 rue Boissy-d'Anglas, 75008 Paris","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","Clef Verte","5 étoiles"],"majSource":"2026-09-01"},{"id":"dt-8fb1b1ea-40a7-3dfa-aeee-523fab064730","cat":"loisirs","ville":"paris","nom":"Paris bike tour","lat":48.862177,"lon":2.352944,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/8fb1b1ea-40a7-3dfa-aeee-523fab064730"}],"recupere":"2026-11-14","long":{"fr":"Profitez des visites guidées à vélo proposées par Paris Bike Tour pour découvrir Paris et la région parisienne sous un autre jour et à quelques tours de roue."},"site":"http://parisbiketour.net/","adresse":"13 Rue Brantôme, 75003 Paris 3e Arrondissement","labels":["Accueil Vélo"],"majSource":"2026-06-24"},{"id":"dt-afec9b5f-2f52-3250-9882-aa5439f34a56","cat":"loisirs","ville":"paris","nom":"Rentabike Paris","lat":48.865241,"lon":2.351051,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/afec9b5f-2f52-3250-9882-aa5439f34a56"}],"recupere":"2026-11-14","long":{"fr":"Rentabike Paris est une agence de location de vélo. Elle propose également de découvrir la capitale autrement, à l'occasion de visites guidées en petit groupe."},"site":"https://rentabikeparis.fr/fr/","adresse":"20 rue Greneta, 75002 Paris","labels":["Accueil Vélo"],"majSource":"2025-04-03"},{"id":"dt-cfe96e8e-6ce2-3059-9482-20b74242e05b","cat":"loisirs","ville":"paris","nom":"Paris à vélo","lat":48.86113,"lon":2.370355,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/cfe96e8e-6ce2-3059-9482-20b74242e05b"}],"recupere":"2026-11-14","long":{"fr":"Pour découvrir Paris autrement, \"Paris à Vélo\" propose des visites guidées ou locations de vélo pour toute la famille."},"site":"https://parisavelo.fr/","adresse":"22 rue Alphonse Baudin, 75011 Paris 11e Arrondissement","labels":["Accueil Vélo"],"majSource":"2026-06-24"},{"id":"dt-d0fbed9f-5a58-3c98-9be1-15eb16f15b0a","cat":"loisirs","ville":"paris","nom":"Le Son de la Terre","lat":48.851475,"lon":2.35111,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/d0fbed9f-5a58-3c98-9be1-15eb16f15b0a"}],"recupere":"2026-11-14","long":{"fr":"Amarré au quai de Montebello, le \"Son de la Terre\" offre une vue imprenable sur Notre-Dame de Paris. Pensé par l'agence Seine Design, cet espace élégant est un lieu unique au cœur de la capitale depuis 2023, avec sa vue panoramique sur la Seine. Ce restaurant bistronomique célèbre les cuisines du monde, propose des concerts, soirées club et accueille des artistes en résidence. Modulable, il offre des espaces privatisables et une scène mobile, ainsi qu'une grande terrasse de 200m2 avec une cuisine maison et des cocktails originaux. Une adresse incontournable à découvrir!"},"site":"https://www.sondelaterre.fr/","adresse":"2 Port de Montebello, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-3b9a9636-9d35-3568-ae4b-29c979673fc1","cat":"musees","ville":"paris","nom":"FEB - Fonds Enki Bilal","lat":48.86218,"lon":2.361931,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/3b9a9636-9d35-3568-ae4b-29c979673fc1"}],"recupere":"2026-11-14","long":{"fr":"Situé dans le 3e arrondissement de Paris, le Fonds Enki Bilal (FEB) est un nouveau lieu culturel hybride inauguré en juin 2026. Conçu par l’artiste pluridisciplinaire Enki Bilal - dessinateur, peintre, scénographe et réalisateur - cet espace se veut un laboratoire vivant et perméable dédié à la création contemporaine. Au-delà de l’exposition de l’œuvre de son fondateur, le fonds propose une programmation ouverte à d’autres imaginaires à travers des cartes blanches, des rencontres, des tables rondes et des projections."},"site":"https://fonds-enki-bilal.com/","adresse":"22-24 rue Charlot, 75003 Paris","majSource":"2026-09-01"},{"id":"dt-5cf55e1b-8e2d-3a77-959f-a6f8f2d3c384","cat":"musees","ville":"paris","nom":"Musée du Barreau de Paris","lat":48.86406,"lon":2.345081,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5cf55e1b-8e2d-3a77-959f-a6f8f2d3c384"}],"recupere":"2026-11-14","long":{"fr":"Plongez dans l'histoire de France à travers le musée, avec des siècles d’événements racontés à travers des œuvres d’art et des documents originaux. Découvrez la vie de figures emblématiques comme Louis XVI, Marie-Antoinette, Léon Gambetta et Raymond Poincaré. De l’affaire Dreyfus au procès de Zola, explorez les dessous de la justice et de la politique. La collection de plaidoiries offre un aperçu unique du monde des avocats, des stratégies de défense de Chauveau-Lagarde à Jacques Isorni. Une plongée fascinante dans l'histoire judiciaire pour mieux appréhender le passé et les enjeux actuels."},"site":"https://www.museedubarreaudeparis.com/","adresse":"25 rue du Jour, 75001 Paris","majSource":"2026-09-01"},{"id":"dt-b9a8de1f-447c-3755-b280-042e66c39a01","cat":"musees","ville":"paris","nom":"La Maison Pompidou","lat":48.861371,"lon":2.352268,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/b9a8de1f-447c-3755-b280-042e66c39a01"}],"recupere":"2026-11-14","long":{"fr":"Située sur la place Georges Pompidou, la Maison Pompidou occupe désormais le bâtiment qui abritait l'Atelier Brancusi. Ce nouveau lieu de vie et d'information accompagne le grand chantier de rénovation du Centre Pompidou. Ouvert à tous, cet espace hybride propose une programmation culturelle variée - expositions, ateliers, rencontres et événements - dédiée à l'histoire du Centre, à son architecture emblématique et aux coulisses de sa transformation. Un point de ralliement incontournable pour rester connecté à l'institution durant sa période de travaux."},"site":"https://www.centrepompidou.fr/fr/lieu/maison-pompidou","adresse":"Place Georges Pompidou, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-fc7e42b4-fff2-36b3-bd95-7dd1284b0102","cat":"musees","ville":"paris","nom":"Musée de la Chasse et de la Nature","lat":48.861404,"lon":2.3587,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/fc7e42b4-fff2-36b3-bd95-7dd1284b0102"}],"recupere":"2026-11-14","long":{"fr":"Le Musée de la Chasse et de la Nature, situé dans le Marais à Paris, se distingue par son charme singulier. Implanté dans deux hôtels particuliers, il propose une expérience hors du commun en plongeant les visiteurs dans l'univers envoûtant d'un amateur d'art passionné. Des oeuvres de grands artistes tels que Rubens, Breughel et Chardin côtoient des créations contemporaines qui questionnent notre relation avec le règne animal. L'ambiance artistique d'époque et les trésors insolites captivent les esprits curieux, offrant une sortie familiale idéale."},"site":"https://www.chassenature.org/","adresse":"62 rue des Archives, 75003 Paris","majSource":"2026-09-01"},{"id":"dt-4cf6c2a3-a6aa-3ec4-8af4-fed9a7a46c2b","cat":"shopping","ville":"paris","nom":"Maison du label \"Fabriqué à Paris\"","lat":48.8451,"lon":2.342216,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4cf6c2a3-a6aa-3ec4-8af4-fed9a7a46c2b"}],"recupere":"2026-11-14","long":{"fr":"Située au 218 rue Saint-Jacques dans le 5e arrondissement, la Maison du label \"Fabriqué à Paris\" est la première vitrine physique entièrement dédiée à l'artisanat parisien d'excellence. Inauguré en février 2026, cet espace de rencontre et d'exposition met en lumière les créations des artisans, créateurs et entrepreneurs labellisés par la Ville de Paris."},"site":"https://www.bdmma.paris/les-prix/le-label-fabrique-a-paris/","adresse":"218 rue Saint-Jacques, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-51a96924-0ea4-36d3-8d03-0b32ac9116ba","cat":"patrimoine","ville":"paris","nom":"Église Saint-Gervais Saint-Protais","lat":48.855614,"lon":2.354459,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/51a96924-0ea4-36d3-8d03-0b32ac9116ba"}],"recupere":"2026-11-14","long":{"fr":"L'église du Marais, entre gothique et classique, fascine par son mélange de styles. La nef en gothique flamboyant du XVIe siècle contraste avec la façade classique, joyau du siècle suivant. Son intérieur est somptueusement décoré, avec une couronne de pierre ornant la clef de voûte de la chapelle de la Vierge. Les vitraux de la chapelle Saint-Jean-Baptiste, datant de 1531, illustrent la Sagesse de Salomon. Un véritable trésor architectural à découvrir pour les amateurs d'Histoire et d'art !"},"site":"https://paris.fraternites-jerusalem.org/","adresse":"13 rue des Barres, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-ea497b9f-69a9-3ba6-a7a1-e24996c83882","cat":"shopping","ville":"paris","nom":"The Perfect Unboxing","lat":48.853482,"lon":2.348825,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/ea497b9f-69a9-3ba6-a7a1-e24996c83882"}],"recupere":"2026-11-14","long":{"fr":"The Perfect Unboxing offre une expérience de cadeau sur mesure grâce à son service de personal shopper. Chaque cadeau est personnalisé en fonction des goûts du destinataire et du budget du client, avec des marques éthiques de haute qualité. Plus de 80% des partenaires sont des femmes entrepreneures françaises, ce qui soutient l'économie locale et l'entrepreneuriat féminin. Des coffrets originaux pour toutes les occasions sont proposés. N'hésitez plus, découvrez cette expérience unique dès maintenant!"},"site":"https://www.the-perfect-unboxing.com/","adresse":"NC, 75 Paris","majSource":"2026-09-01"},{"id":"dt-aff4d905-45da-3ce9-a058-2a4617311c46","cat":"patrimoine","ville":"paris","nom":"L'Académie du climat","lat":48.856277,"lon":2.355838,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/aff4d905-45da-3ce9-a058-2a4617311c46"}],"recupere":"2026-11-14","long":{"fr":"L'Académie du climat, à proximité de l'Hôtel de Ville, est un lieu clé pour sensibiliser les jeunes aux enjeux environnementaux. Près de l'église Saint-Gervais Saint-Protais, elle propose diverses activités en semaine : cuisine, bricolage, jardinage, couture, écoconstruction, pépinière, etc. Des conférences, ateliers et expositions gratuites sur l'environnement sont également disponibles en soirée et le week-end. Une offre complète pour former et mobiliser les jeunes de 9 à 25 ans."},"site":"https://www.academieduclimat.paris/","adresse":"2 place Baudoyer, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-838056d9-cebe-3366-9438-164699c74203","cat":"restaurants","ville":"paris","nom":"Jaja.","lat":48.857517,"lon":2.35725,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/838056d9-cebe-3366-9438-164699c74203"}],"recupere":"2026-11-14","long":{"fr":"Au cœur du Marais, quartier historique LGBT de Paris, le Jaja offre une pause bucolique dans un charmant passage, loin de l'agitation de la rue. Sa terrasse fleurie crée une ambiance champêtre pour déguster une cuisine bistronomique mettant en avant des produits frais, bio et de saison, accompagnés d'une sélection de plus de 80 vins. Une formule enfant est disponible et une salle voûtée au sous-sol peut être réservée pour des événements privés. Une adresse paisible au cœur de la capitale."},"site":"http://www.jaja-resto.com/","adresse":"3 rue Sainte-Croix de la Bretonnerie, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-e7f7a90d-a10c-3bce-a82f-e25d2b99f458","cat":"patrimoine","ville":"paris","nom":"Hotel de Ville de Paris","lat":48.856483,"lon":2.352413,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/e7f7a90d-a10c-3bce-a82f-e25d2b99f458"}],"recupere":"2026-11-14","long":{"fr":"Depuis 1357, l'Hôtel de Ville de Paris est le siège de la municipalité parisienne. Reconstruit en style néo-renaissance après l'incendie de 1871, ce bâtiment emblématique est chargé d'histoire. Il propose des visites guidées sur réservation, mettant en valeur la magnifique Salle des Fêtes rappelant la galerie des glaces de Versailles. Des expositions gratuites y attirent un large public, offrant une immersion dans la vie politique et culturelle de la capitale."},"site":"https://www.paris.fr/","adresse":"Mairie de Paris - Place de l'Hôtel de Ville, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-d2f5eea8-5e23-36de-b4f5-5980c024b5af","cat":"restaurants","ville":"paris","nom":"Le Stock Paris","lat":48.870168,"lon":2.339384,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/d2f5eea8-5e23-36de-b4f5-5980c024b5af"}],"recupere":"2026-11-14","long":{"fr":"Situé au cœur du 2e arrondissement, à deux pas de la Bourse, Le Stock Paris est un restaurant et lieu de vie hybride au style vintage inspiré des années 70. Sous la direction du chef Ali Ourti, l'établissement propose une cuisine d'instinct aux accents méditerranéens et kabyles, privilégiant les produits frais et de saison."},"site":"https://www.stock-paris.fr/","adresse":"88 rue de Richelieu, 75002 Paris","majSource":"2026-09-01"},{"id":"dt-7a1dbf45-2664-3cef-8872-9937d59b4884","cat":"cafes","ville":"paris","nom":"Le Cox","lat":48.858227,"lon":2.354844,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/7a1dbf45-2664-3cef-8872-9937d59b4884"}],"recupere":"2026-11-14","long":{"fr":"Le Cox est un lieu incontournable des nuits gays parisiennes, où les hommes barbus et moustachus sont les bienvenus. Son ambiance conviviale et \"fetish\" attire une clientèle en quête de rencontres intéressantes. La terrasse bondée est appréciée pour son cadre décontracté. Les \"happy hours\" de 18h à 22h séduisent les habitués avec des tarifs attractifs. Que ce soit pour un verre entre amis ou pour de nouvelles rencontres, le Cox répond aux attentes des noctambules parisiens."},"site":"https://cox.fr/","adresse":"15 rue des Archives, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-723774f1-7a14-33a3-baa4-f824c8875082","cat":"patrimoine","ville":"paris","nom":"Collège des Bernardins","lat":48.84874,"lon":2.352035,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/723774f1-7a14-33a3-baa4-f824c8875082"}],"recupere":"2026-11-14","long":{"fr":"Le Collège des Bernardins, rénové par l'église catholique de Paris, est un lieu de partage et de découverte. L'École Cathédrale propose des cours pour tous et encourage la réflexion. Sa programmation variée attire un large public avec des expositions, des concerts, des débats et des conférences. Témoin de l'Université médiévale de Paris, le site offre une ambiance conviviale avec une librairie, un café-restaurant et un jardin. Des concerts ludiques sont également organisés pour initier les enfants à l'art et à la musique."},"site":"https://www.collegedesbernardins.fr/","adresse":"20 rue de Poissy, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-2a318712-7316-3582-a749-48852368d986","cat":"shopping","ville":"paris","nom":"Aux Merveilleux de Fred","lat":48.85572,"lon":2.356386,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/2a318712-7316-3582-a749-48852368d986"}],"recupere":"2026-11-14","long":{"fr":"Dans le quartier du Marais, une boutique célèbre pour ses Merveilleux ravit les amateurs de sucreries. Cette pâtisserie emblématique du Nord de la France allie meringue et crème fouettée. Frédéric Vaucamps propose 5 variations délicieuses : Magnifique, Sans-Culotte, Excentrique, Impensable et Incroyable. Découvrez ces créations savoureuses ainsi que les revisites des traditionnels cramiques, de délicieux petits pains briochés. Une escapade gourmande à savourer sans modération!"},"site":"http://www.auxmerveilleux.com/","adresse":"24 rue du Pont Louis Philippe, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-bfcbc7bc-6164-3d8b-b23a-97a0002c8b16","cat":"restaurants","ville":"paris","nom":"Au Bourguignon du Marais","lat":48.855442,"lon":2.357581,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/bfcbc7bc-6164-3d8b-b23a-97a0002c8b16"}],"recupere":"2026-11-14","long":{"fr":"Le Bourguignon du Marais, sur les bords de la Seine, enchante toujours avec sa cuisine traditionnelle et son savoir-faire reconnu à Paris. Au menu, les grands classiques du bistrot : œufs en meurette, rognons de veau à la moutarde, escargots, foie gras... Mais la vedette reste le bœuf bourguignon, mijoté dans sa cocotte. Pour parfaire ce festin, choisissez un cru parmi la belle sélection de vins proposée. Un délice pour les papilles à savourer dans un cadre authentique et chaleureux."},"site":"http://aubourguignondumarais.fr/","adresse":"52 rue François Miron, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-5e3de2b6-03ee-3a23-b1b0-d69575138b10","cat":"patrimoine","ville":"paris","nom":"Église Saint-Louis-en-l'Île","lat":48.851345,"lon":2.357504,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5e3de2b6-03ee-3a23-b1b0-d69575138b10"}],"recupere":"2026-11-14","long":{"fr":"Construite entre 1664 et 1726 par l'architecte Le Vau, l'église Saint-Louis possède un clocher original avec une horloge datant de 1741. A l'intérieur, on peut admirer des œuvres d'art comme \"Les Pèlerins d'Emmaüs\" de Coypel (1746) ou une \"Annonciation\" de Fra Angelico. On y trouve aussi un \"Saint-François de Salle\" de Noël Hallé et une toile de Carle Van Loo (1742) représentant Saint-Jean et Saint-Pierre guérissant un boiteux. Une visite incontournable pour découvrir ce patrimoine artistique exceptionnel."},"site":"http://www.saintlouisenlile.catholique.fr/","adresse":"19 bis rue Saint-Louis-en-l'Île, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-fc81f548-ca08-3061-b5ad-9e714bc334e3","cat":"parcs","ville":"paris","nom":"Jardin des Arts - Albert Schweitzer","lat":48.853832,"lon":2.35794,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/fc81f548-ca08-3061-b5ad-9e714bc334e3"}],"recupere":"2026-11-14","long":{"fr":"Le Jardin des Arts - Albert Schweitzer, situé dans le quartier du Marais à Paris, est un espace vert réaménagé en 2020 suite à la fusion du square Albert Schweitzer, du jardin de la Cité des Arts et du jardin à la française de l'hôtel d'Aumont. Ses allées ombragées et pelouses fleuries en font un lieu idéal pour se détendre, avec des bancs en poutres pour une pause bien méritée. Les enfants apprécieront l'espace de jeux qui leur est dédié. Une escapade agréable au cœur de la ville lumière."},"site":"https://www.paris.fr/","adresse":"10 rue de l'Hôtel de Ville, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-dc483399-03e0-35d9-8db5-3b7dc3fe2db9","cat":"restaurants","ville":"paris","nom":"Dans le Noir ?","lat":48.861347,"lon":2.350561,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/dc483399-03e0-35d9-8db5-3b7dc3fe2db9"}],"recupere":"2026-11-14","long":{"fr":"Le restaurant Dans le Noir ? à Paris propose une expérience culinaire unique dans l'obscurité. Le chef Yann Deslandes concocte un menu surprise avec des ingrédients bio et de saison en circuit court pour éveiller vos sens. Redécouvrez le goût, l'odorat, le toucher et l'ouïe dans une ambiance conviviale. Des guides insolites vous accompagnent pour une expérience sensorielle inoubliable. Bénéficiez de réductions pour les groupes de 10 personnes et plus. Une expérience à partager absolument !"},"site":"https://paris.danslenoir.com/","adresse":"51 rue Quincampoix, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-89efc34f-efac-3c6e-bd76-01b4dbb4b884","cat":"patrimoine","ville":"paris","nom":"Grande Mosquée de Paris","lat":48.842384,"lon":2.35469,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/89efc34f-efac-3c6e-bd76-01b4dbb4b884"}],"recupere":"2026-11-14","long":{"fr":"Construite entre 1922 et 1926, la Mosquée de Paris se trouve dans le Quartier latin, à côté du Muséum d'Histoire Naturelle. Son architecture hispano-mauresque, avec un minaret de 33 mètres, rappelle l'Alhambra de Grenade. Le patio orné d'arcades crée une atmosphère enchanteresse, et la salle de prière est décorée de motifs magnifiques et de tapis somptueux. En plus de sa fonction religieuse, la Mosquée de Paris propose des services de hammam, un restaurant, un salon de thé et une boutique exotique évoquant les marchés orientaux. Un endroit unique mêlant culture et détente."},"site":"https://www.grandemosqueedeparis.fr/","adresse":"2 bis place du Puits-de-l'Ermite, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-5695ad60-533d-3508-a941-a5b1b827c8ff","cat":"restaurants","ville":"paris","nom":"Le chant des voyelles","lat":48.859077,"lon":2.350186,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5695ad60-533d-3508-a941-a5b1b827c8ff"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé au cœur du Marais, à proximité de l'église Saint-Merri, Le Chant des Voyelles est un incontournable de la rue des Lombards, réputé pour son ambiance conviviale. Le chef propose une cuisine française traditionnelle, mettant en avant des produits frais et de qualité. Sa terrasse sur rue piétonne, ouverte toute l'année, est parfaite pour profiter de l'animation du quartier. Un lieu idéal pour découvrir le bar à huîtres dès l'entrée et se mettre en appétit !"},"site":"http://lechantdesvoyelles.fr/","adresse":"2 rue des Lombards, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-9f48ec4f-5054-3d23-b10f-6fb4b6f32617","cat":"shopping","ville":"paris","nom":"El Ganso","lat":48.856971,"lon":2.359906,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/9f48ec4f-5054-3d23-b10f-6fb4b6f32617"}],"recupere":"2026-11-14","long":{"fr":"Fondée en 2004, la marque espagnole El Ganso est reconnue pour ses collections élégantes et preppy pour hommes, femmes et enfants. En 2012, elle a ouvert une deuxième boutique à Paris, renforçant sa présence sur le marché de la mode. Grâce à son savoir-faire et sa créativité, El Ganso propose des pièces de qualité, suivant les tendances actuelles. Son esprit chic et décontracté séduit une clientèle en quête d'élégance et de modernité, conquérant ainsi de nombreux clients à travers le monde."},"site":"https://www.elganso.com/","adresse":"7 rue des Rosiers, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-f0ebb196-9298-359f-beab-33d397315c57","cat":"restaurants","ville":"paris","nom":"Paris En Scène","lat":48.854452,"lon":2.344755,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/f0ebb196-9298-359f-beab-33d397315c57"}],"recupere":"2026-11-14","long":{"fr":"Profitez d'un dîner croisière sur la Seine dès 42€. Embarquez pour une escapade en bateau d'1h15 à 1h30, idéal pour les emplois du temps chargés. Fauteuils club en cuir, larges baies vitrées, bar, terrasses avant et arrière, pont supérieur en plein air. Réservez une table isolée dans le poste de pilotage pour une soirée romantique (30€ supplément/personne). Possibilité de privatiser le bateau pour 90 convives. Embarquement été au pont Saint-Michel et hiver sur l'île aux Cygnes. Savourez..."},"site":"https://www.paris-en-scene.com/","adresse":"Escale du pont Saint-Michel - 12 quai des Orfèvres, 75001 Paris","majSource":"2026-09-01"},{"id":"dt-84a980c2-fdf2-3def-9b6f-9f9098ad62a1","cat":"cafes","ville":"paris","nom":"Café Beaubourg","lat":48.859978,"lon":2.351017,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/84a980c2-fdf2-3def-9b6f-9f9098ad62a1"}],"recupere":"2026-11-14","long":{"fr":"Face au Centre Georges Pompidou, le Café Beaubourg est prisé pour sa situation idéale. Sa grande terrasse offre une vue magnifique sur l'architecture unique du plus grand musée d'art moderne en Europe. Ouvert en 1987 par Gilbert Costes, ce café au design contemporain par Christian de Portzamparc propose un cadre élégant pour se relaxer ou travailler. Avec un brunch quotidien, c'est l'endroit idéal pour se retrouver entre amis ou savourer une pause loin du tumulte urbain."},"site":"https://cafebeaubourg.com/fr/","adresse":"43 rue Saint-Merri, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-b01f7b9c-780f-3405-8a38-3b3cbc086651","cat":"restaurants","ville":"paris","nom":"Atelier Maître Albert","lat":48.85111,"lon":2.35022,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/b01f7b9c-780f-3405-8a38-3b3cbc086651"}],"recupere":"2026-11-14","long":{"fr":"L'Atelier Maître Albert, extension de la célèbre maison Guy Savoy, est une rôtisserie située dans une rue calme du Quartier Latin, proche de la Seine. Moderne tout en conservant son côté traditionnel, l'établissement propose différents espaces pour tous les goûts : la Vinothèque pour une pause rapide, le salon Bibliothèque pour une atmosphère chaleureuse, et la salle Cheminée pour une ambiance intime et romantique. En cuisine, une délicieuse cuisine de marché généreuse attend les convives."},"site":"http://www.ateliermaitrealbert.com/","adresse":"1 rue Maître Albert, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-41349e5c-e8b5-32d9-95bb-7447aec68422","cat":"restaurants","ville":"paris","nom":"L'As du Fallafel","lat":48.857407,"lon":2.359196,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/41349e5c-e8b5-32d9-95bb-7447aec68422"}],"recupere":"2026-11-14","long":{"fr":"Découvrez l'authentique falafel, véritable boulette de pois chiches, dans le quartier juif de la rue des Rosiers, au cœur du Marais ! Malgré l'afflux de gourmands, laissez-vous tenter par ce vrai falafel cuisiné dans les règles de l'art. Une fois passée l'agitation de la rue, vous pourrez enfin déguster ce délicieux sandwich, préparé avec soin. Envie de changer ? Optez pour le shawarma à l'agneau... À emporter ou à déguster sur place, ce petit restaurant vaut vraiment le détour."},"site":"https://www.instagram.com/lasdufallafel/","adresse":"34 rue des Rosiers, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-1d52b961-e9d8-301d-9b41-bf2633c4af7f","cat":"marches","ville":"paris","nom":"Marché Maubert","lat":48.850082,"lon":2.348511,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/1d52b961-e9d8-301d-9b41-bf2633c4af7f"}],"recupere":"2026-11-14","long":{"fr":"Le marché de Maubert, au cœur du quartier Latin, est un incontournable pour les gourmets. Avec ses 45 stands offrant des produits frais et de qualité, notamment des fruits et légumes bio, on est plongé dans un tourbillon de saveurs et de couleurs. Ce marché promeut une alimentation saine et éthique, en adéquation avec les attentes des consommateurs. Faire ses achats ici, c'est soutenir une agriculture respectueuse de l'environnement. Maubert invite à associer plaisir et santé à chaque repas."},"site":"https://www.paris.fr/marches","adresse":"Place Maubert, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-6dc7e35f-c2ad-3110-90cc-dbdfc009245f","cat":"cafes","ville":"paris","nom":"Le Bar des Maillets d'Argent","lat":48.849981,"lon":2.35491,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/6dc7e35f-c2ad-3110-90cc-dbdfc009245f"}],"recupere":"2026-11-14","long":{"fr":"Le bar du rez-de-chaussée de la Tour est inspiré du polo et de l'équipe des Maillets d'Argent de Claude Terrail. Dans une ambiance réinventée des années 30, le Bar des Maillets d'Argent vous accueille toute la journée, s'adaptant à vos désirs, que ce soit pour un café le matin ou un cocktail le soir, pour un déjeuner, un dîner ou un tea time. Avec son mobilier vintage, ses murs verts et ses fauteuils confortables, laissez-vous charmer par les créations de Mathieu Velmir, le Chef Barman."},"site":"https://tourdargent.com/le-bar-des-maillets-dargent/","adresse":"15 quai de la Tournelle, 75005 Paris","majSource":"2026-09-01"},{"id":"dt-eedf387a-b641-3384-a067-ce5c9c86dedd","cat":"parcs","ville":"paris","nom":"Jardin Nelson Mandela","lat":48.862615,"lon":2.344408,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/eedf387a-b641-3384-a067-ce5c9c86dedd"}],"recupere":"2026-11-14","long":{"fr":"Le Jardin Nelson Mandela, aux Halles, offre une vue sur la Bourse du Commerce, l'église Saint-Eustache et la Canopée du Forum des Halles. Les enfants de 7 à 11 ans peuvent profiter d'un terrain d'aventure de 2 500 m² avec trampoline, mégachines, pont ressort et Mur Dino. Le port de chaussures de sport est obligatoire. Un playground de 400 m² conçu par Romain Froquet propose terrains de foot, basket et tables de ping-pong. Une escapade ludique et sportive au cœur de Paris pour les plus jeunes !"},"site":"https://www.paris.fr/","adresse":"Passage de la Canopée - Rues Rambuteau et Coquillère - Rue de Viarmes - Rue Berger, 75001 Paris","majSource":"2026-09-01"},{"id":"dt-1da57d1e-8b82-3517-b97f-ff56975b81b3","cat":"marches","ville":"paris","nom":"Marché aux fleurs","lat":48.85539,"lon":2.347558,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/1da57d1e-8b82-3517-b97f-ff56975b81b3"}],"recupere":"2026-11-14","long":{"fr":"Sur l'Île de la Cité se situe le marché aux fleurs de la place Louis Lépine, entre Notre-Dame et la Sainte-Chapelle, ouvert en 1830. Ce marché propose une large sélection de fleurs et de plantes sous des pavillons d'époque 1900, des espèces locales aux variétés exotiques comme les orchidées. À Paris, ne manquez pas le marché de la Madeleine et celui des Ternes pour une diversité florale quotidienne. Explorez les trésors végétaux de la capitale !"},"site":"https://www.paris.fr/marches","adresse":"Place Louis Lépine - Quai de la Corse, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-bf168f64-e5b8-34a7-a6a9-75692f7710a1","cat":"parcs","ville":"paris","nom":"Square Jean XXIII","lat":48.852573,"lon":2.350971,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/bf168f64-e5b8-34a7-a6a9-75692f7710a1"}],"recupere":"2026-11-14","long":{"fr":"Le square Jean XXIII, situé en arrière de la majestueuse cathédrale Notre-Dame de Paris, offre un refuge de quiétude au cœur de l'effervescence urbaine. Parsemé de bancs accueillants et d'arbres ombrageux, cet endroit s'avère idéal pour une pause détente ou un repas sur le pouce, loin du flot incessant de visiteurs de la cathédrale. La vue imprenable sur le chevet de l'édifice ajoute une touche de magie à ce petit coin de verdure au charme indéniable."},"site":"https://www.paris.fr/","adresse":"4 place du Parvis Notre-Dame, 75004 Paris","majSource":"2026-09-01"},{"id":"dt-1f6e884f-0c7a-3b3e-ae4c-644d30d249e3","cat":"chateaux","ville":"paris","nom":"Conciergerie","lat":48.855675,"lon":2.345939,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/1f6e884f-0c7a-3b3e-ae4c-644d30d249e3"}],"recupere":"2026-11-14","long":{"fr":"Au cœur de Paris, au bord de la Seine, visitez la Conciergerie, le plus ancien témoignage du Palais de la Cité, première demeure royale de la capitale et prison lors de la Révolution française. Une véritable plongée dans l'Histoire de France !"},"site":"http://www.paris-conciergerie.fr/","adresse":"2 boulevard du Palais, 75001 Paris","majSource":"2026-08-24"},{"id":"dt-8808c1d7-b4fe-39b6-aa64-25c6d4ec2bc3","cat":"animaux","ville":"paris","nom":"Ménagerie, le zoo du Jardin des Plantes","lat":48.845699,"lon":2.360069,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/8808c1d7-b4fe-39b6-aa64-25c6d4ec2bc3"}],"recupere":"2026-11-14","long":{"fr":"Nichée dans un havre de paix et de verdure, la ménagerie, zoo du jardin des plantes, abrite quelques 200 espèces, dont un tiers est menacé d’extinction. Ne manquez pas cette promenade dépaysante en plein cœur de Paris."},"site":"https://www.mnhn.fr/fr/menagerie-zoo-du-jardin-des-plantes","adresse":"57 rue Cuvier, 75005 Paris 5e Arrondissement","majSource":"2025-08-21"},{"id":"dt-d12b9936-519e-31a8-8761-81fba6bc0e2c","cat":"chateaux","ville":"paris","nom":"La Nef du Grand Palais","lat":48.866119,"lon":2.313314,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Choose Paris Region","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/d12b9936-519e-31a8-8761-81fba6bc0e2c"}],"recupere":"2026-11-14","long":{"fr":"Au cœur de Paris, sur l’avenue des Champs-Élysées, construit pour l’Exposition universelle de 1900 et consacré « par la République à la gloire de l’art français », la Nef de 13500 m2 est la plus grande verrière d’Europe."},"site":"http://www.grandpalais.fr/","adresse":"Avenue Winston Churchill, 75008 Paris","majSource":"2026-06-23"},{"id":"dt-f57eebca-0721-3d2c-bdc4-b874c5891f1d","cat":"animaux","ville":"paris","nom":"La Ménagerie, le zoo du Jardin des plantes - Muséum national d'histoire naturel","lat":48.844273,"lon":2.36041,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/f57eebca-0721-3d2c-bdc4-b874c5891f1d"}],"recupere":"2026-11-14","long":{"fr":"Envie de sortie en famille ? La Ménagerie du Jardin des Plantes est parfaite ! Fondée en 1794 à Paris, c'est l'un des plus anciens zoos au monde. Venez admirer une grande diversité d'espèces sur ses 5,5 hectares. La Ménagerie contribue à la préservation d'espèces menacées. Ne manquez pas la singerie, la fauverie et les vivariums avec des animaux rares. Une expérience fascinante en famille !"},"adresse":"Place Valhubert, 75005 Paris","majSource":"2026-09-01"}]);
